    const isAllComplete = tasks.every(t => t.completed);
    if (isAllComplete) return null;

    return (
        <Card className="bg-gradient-to-br from-blue-50 to-indigo-100 dark:from-blue-900/30 dark:to-indigo-900/30 animate-fade-in-up">
