import React, { useState, useEffect } from 'react';
import { supabase } from '../../lib/supabaseClient';
import { useAppContext } from '../../context/AppContext';
import { useNotifier } from '../../context/NotificationContext';
import Card from '../ui/Card';
import Button from '../ui/Button';
import { XIcon, SparklesIcon, CheckCircleIcon, XCircleIcon, QuestionMarkCircleIcon, LightBulbIcon } from '../ui/Icons';
import { GoogleGenAI, Type } from "@google/genai";
import { UserCourseMaterial, MaterialQuizQuestion } from '../../types';
import { marked } from 'marked';

interface MaterialQuizModalProps {
    material: UserCourseMaterial;
    onClose: () => void;
}

const MaterialQuizModal: React.FC<MaterialQuizModalProps> = ({ material, onClose }) => {
    const { currentUser } = useAppContext();
    const { addToast } = useNotifier();

    // States
    const [loading, setLoading] = useState(true);
    const [generating, setGenerating] = useState(false);
    const [quizQuestions, setQuizQuestions] = useState<MaterialQuizQuestion[]>([]);
    const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
    const [selectedOption, setSelectedOption] = useState<number | null>(null);
    const [score, setScore] = useState(0);
    const [isFinished, setIsFinished] = useState(false);
    const [quizId, setQuizId] = useState<string | null>(null);
    const [showResult, setShowResult] = useState(false); // To show correct/incorrect after selection

    // Tips State
    const [tips, setTips] = useState<string | null>(null);
    const [generatingTips, setGeneratingTips] = useState(false);

    useEffect(() => {
        checkAndLoadQuiz();
    }, [material.id]);

    const checkAndLoadQuiz = async () => {
        if (!supabase) return;
        setLoading(true);

        // 1. Check if a quiz exists for this material
        const { data: existingQuiz, error: quizError } = await supabase
            .from('material_quizzes')
            .select('id')
            .eq('material_id', material.id)
            .maybeSingle();

        if (existingQuiz) {
            setQuizId(existingQuiz.id);
            // Load questions
            const { data: questions, error: qError } = await supabase
                .from('material_quiz_questions')
                .select('*')
                .eq('quiz_id', existingQuiz.id);

            if (questions) setQuizQuestions(questions);
            setLoading(false);
        } else {
            // No quiz exists, we need to generate one
            setLoading(false);
            // We stay in a "ready to generate" state
        }
    };

    const generateTips = async () => {
        if (!currentUser) return;
        setGeneratingTips(true);
        try {
            const apiKey = process.env.API_KEY;
            if (!apiKey) throw new Error("AI key missing");
            const ai = new GoogleGenAI({ apiKey });

            const prompt = `You are an experienced academic coach. A student is preparing for an exam on the course "${material.courses?.code || 'Unknown'} - ${material.courses?.name || 'General'}" using the material titled "${material.title}". 

            Provide 3-5 concise, high-impact study tips specifically for passing an exam on this topic. Highlight common pitfalls if applicable. Keep it encouraging and brief. Format with Markdown bullet points.`;

            const response = await ai.models.generateContent({
                model: 'gemini-2.5-flash',
                contents: prompt,
            });

            setTips(response.text || "No tips generated.");
        } catch (error: any) {
            console.error("Error generating tips:", error);
            addToast("Could not generate tips at this time.", "error");
        } finally {
            setGeneratingTips(false);
        }
    };

    const generateQuiz = async () => {
        if (!currentUser || !supabase) return;
        setGenerating(true);

        try {
            // 1. Fetch file from storage
            // We need to parse the path from the URL or assume it was stored in `file_path`
            const path = material.file_path || new URL(material.file_url).pathname.split('/academic_uploads/')[1];

            const { data: fileBlob, error: downloadError } = await supabase.storage
                .from('academic_uploads')
                .download(path);

            if (downloadError) throw new Error("Could not download file for analysis.");

            // 2. Convert to Base64
            const base64Data = await new Promise<string>((resolve) => {
                const reader = new FileReader();
                reader.readAsDataURL(fileBlob);
                reader.onload = () => resolve((reader.result as string).split(',')[1]);
            });

            // 3. Call Gemini
            const apiKey = process.env.API_KEY;
            if (!apiKey) throw new Error("AI key missing");
            const ai = new GoogleGenAI({ apiKey });

            const prompt = `You are a strict academic examiner. Based on the provided document, generate 5 multiple-choice questions to test a student's understanding.

            Return ONLY a valid JSON array of objects. Each object must have:
            - question_text (string)
            - options (array of 4 strings)
            - correct_option_index (integer, 0-3)`;

            const response = await ai.models.generateContent({
                model: 'gemini-2.5-flash',
                contents: {
                    parts: [
                        { inlineData: { mimeType: fileBlob.type, data: base64Data } },
                        { text: prompt }
                    ]
                },
                config: {
                    responseMimeType: "application/json",
                    responseSchema: {
                        type: Type.ARRAY,
                        items: {
                            type: Type.OBJECT,
                            properties: {
                                question_text: { type: Type.STRING },
                                options: { type: Type.ARRAY, items: { type: Type.STRING } },
                                correct_option_index: { type: Type.INTEGER }
                            }
                        }
                    }
                }
            });

            const generatedQuestions = JSON.parse(response.text || '[]');

            if (generatedQuestions.length === 0) throw new Error("AI could not generate questions.");

            // 4. Save to DB
            // Create Quiz Record
            const { data: newQuiz, error: insertQuizError } = await supabase
                .from('material_quizzes')
                .insert({ material_id: material.id, created_by: currentUser.id })
                .select()
                .single();

            if (insertQuizError) throw insertQuizError;
            setQuizId(newQuiz.id);

            // Create Questions
            const questionsPayload = generatedQuestions.map((q: any) => ({
                quiz_id: newQuiz.id,
                question_text: q.question_text,
                options: q.options,
                correct_option_index: q.correct_option_index
            }));

            const { data: savedQuestions, error: insertQError } = await supabase
                .from('material_quiz_questions')
                .insert(questionsPayload)
                .select();

            if (insertQError) throw insertQError;

            setQuizQuestions(savedQuestions as MaterialQuizQuestion[]);

        } catch (error: any) {
            console.error("Quiz generation error:", error);
            addToast(`Failed to generate quiz: ${error.message}`, 'error');
        } finally {
            setGenerating(false);
        }
    };

    const handleOptionSelect = (index: number) => {
        if (showResult) return; // Prevent changing answer after reveal
        setSelectedOption(index);
        setShowResult(true);

        const currentQ = quizQuestions[currentQuestionIndex];
        if (index === currentQ.correct_option_index) {
            setScore(s => s + 1);
        }

        // Auto advance after short delay
        setTimeout(() => {
            if (currentQuestionIndex < quizQuestions.length - 1) {
                setCurrentQuestionIndex(p => p + 1);
                setSelectedOption(null);
                setShowResult(false);
            } else {
                finishQuiz(score + (index === currentQ.correct_option_index ? 1 : 0));
            }
        }, 1500);
    };

    const finishQuiz = async (finalScore: number) => {
        setIsFinished(true);
        if (!currentUser || !supabase || !quizId) return;

        // Record Attempt
        await supabase.from('material_quiz_attempts').insert({
            quiz_id: quizId,
            user_id: currentUser.id,
            score: finalScore,
            total_questions: quizQuestions.length
        });

        // Gamification: Give 10 coins for a perfect score
        if (finalScore === quizQuestions.length) {
             await supabase.from('coin_transactions').insert({
                user_id: currentUser.id,
                source_type: 'task', // Reusing task type or can add specific 'quiz' type if enum allows
                source_id: quizId,
                coin_amount: 10,
                status: 'approved',
                reason: `Perfect score on ${material.title} quiz`
            });
            await supabase.rpc('increment_coins', { amount: 10, user_id: currentUser.id }); // Assuming this RPC exists or handle via transaction
            addToast("Perfect Score! You earned 10 coins.", 'success');
        }
    };

    return (
        <div className="fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-4 animate-fade-in-up">
            <Card className="w-full max-w-lg relative max-h-[90vh] overflow-y-auto flex flex-col">
                <button onClick={onClose} className="absolute top-4 right-4 text-gray-400 hover:text-gray-600">
                    <XIcon className="w-6 h-6" />
                </button>

                <div className="text-center mb-6">
                    <h2 className="text-xl font-bold text-gray-800 dark:text-white">Genius Quiz</h2>
                    <p className="text-sm text-gray-500 truncate">{material.title}</p>
                </div>

                {loading ? (
                    <div className="py-10 text-center">Loading...</div>
                ) : !quizQuestions.length ? (
                    <div className="py-8 text-center space-y-4">
                        <QuestionMarkCircleIcon className="w-16 h-16 mx-auto text-primary-500" />
                        <p className="text-gray-600 dark:text-gray-300">
                            No quiz exists for this material yet. Be the first to generate one using AI!
                        </p>

                        {/* AI Tips Section */}
                        {!tips ? (
                            <Button onClick={generateTips} disabled={generatingTips} variant="outline" className="w-full">
                                {generatingTips ? 'Thinking...' : <><LightBulbIcon className="w-4 h-4 mr-2" /> Get Exam Tips First</>}
                            </Button>
                        ) : (
                            <div className="bg-yellow-50 dark:bg-yellow-900/30 border border-yellow-200 dark:border-yellow-700 rounded-lg p-4 text-left">
                                <h4 className="font-bold text-yellow-800 dark:text-yellow-200 mb-2 flex items-center gap-2">
                                    <LightBulbIcon className="w-4 h-4" /> Exam Strategy
                                </h4>
                                <div 
                                    className="prose prose-sm dark:prose-invert max-w-none text-sm text-gray-800 dark:text-gray-200"
                                    dangerouslySetInnerHTML={{ __html: marked.parse(tips) }}
                                ></div>
                            </div>
                        )}

                        <Button onClick={generateQuiz} disabled={generating} className="w-full">
                            {generating ? (
                                <span className="flex items-center gap-2">
                                    <SparklesIcon className="w-4 h-4 animate-spin" /> Generating...
                                </span>
                            ) : (
                                <span className="flex items-center gap-2">
                                    <SparklesIcon className="w-4 h-4" /> Generate Quiz with AI
                                </span>
                            )}
                        </Button>
                        {generating && <p className="text-xs text-gray-400">Reading document and crafting questions...</p>}
                    </div>
                ) : isFinished ? (
                    <div className="py-8 text-center space-y-4">
                        {score === quizQuestions.length ? (
                            <div className="w-20 h-20 bg-green-100 rounded-full flex items-center justify-center mx-auto">
                                <CheckCircleIcon className="w-12 h-12 text-green-600" />
                            </div>
                        ) : (
                            <div className="w-20 h-20 bg-yellow-100 rounded-full flex items-center justify-center mx-auto">
                                <span className="text-3xl font-bold text-yellow-600">{score}</span>
                            </div>
                        )}
                        <h3 className="text-2xl font-bold">You scored {score}/{quizQuestions.length}</h3>
                        <p className="text-gray-500">
                            {score === quizQuestions.length ? "You're an Academic Giant! Perfect score." : "Good effort! Keep studying."}
                        </p>
                        <Button onClick={onClose} className="w-full">Close</Button>
                    </div>
                ) : (
                    <div className="space-y-6">
                        {/* Tips Section before starting question loop */}
                        {!tips && currentQuestionIndex === 0 && (
                             <div className="mb-4 text-center">
                                <button 
                                    onClick={generateTips} 
                                    disabled={generatingTips}
                                    className="text-xs text-primary-600 hover:underline flex items-center justify-center gap-1 mx-auto"
                                >
                                    {generatingTips ? 'Generating...' : <><LightBulbIcon className="w-3 h-3" /> Need a hint? Get Exam Tips</>}
                                </button>
                             </div>
                        )}

                        {tips && (
                            <div className="bg-yellow-50 dark:bg-yellow-900/30 border border-yellow-200 dark:border-yellow-700 rounded-lg p-3 mb-4 text-left">
                                <details>
                                    <summary className="font-bold text-yellow-800 dark:text-yellow-200 text-sm cursor-pointer flex items-center gap-2">
                                        <LightBulbIcon className="w-4 h-4" /> View Exam Tips
                                    </summary>
                                    <div 
                                        className="prose prose-sm dark:prose-invert max-w-none text-sm text-gray-800 dark:text-gray-200 mt-2"
                                        dangerouslySetInnerHTML={{ __html: marked.parse(tips) }}
                                    ></div>
                                </details>
                            </div>
                        )}

                        {/* Progress Bar */}
                        <div className="w-full bg-gray-200 rounded-full h-2 dark:bg-gray-700">
                            <div 
                                className="bg-primary-600 h-2 rounded-full transition-all duration-300" 
                                style={{ width: `${((currentQuestionIndex + 1) / quizQuestions.length) * 100}%` }}
                            ></div>
                        </div>

                        {/* Question */}
                        <div>
                            <span className="text-xs font-bold text-gray-500 uppercase">Question {currentQuestionIndex + 1} of {quizQuestions.length}</span>
                            <h3 className="text-lg font-semibold mt-1">{quizQuestions[currentQuestionIndex].question_text}</h3>
                        </div>

                        {/* Options */}
                        <div className="space-y-3">
                            {quizQuestions[currentQuestionIndex].options.map((option, idx) => {
                                let btnClass = "w-full text-left p-4 rounded-lg border-2 transition-all ";
                                const isCorrect = idx === quizQuestions[currentQuestionIndex].correct_option_index;
                                const isSelected = selectedOption === idx;

                                if (showResult) {
                                    if (isCorrect) btnClass += "bg-green-100 border-green-500 text-green-800 dark:bg-green-900/30";
                                    else if (isSelected) btnClass += "bg-red-100 border-red-500 text-red-800 dark:bg-red-900/30";
                                    else btnClass += "border-gray-200 dark:border-gray-700 opacity-50";
                                } else {
                                    btnClass += "border-gray-200 dark:border-gray-700 hover:border-primary-500 hover:bg-primary-50 dark:hover:bg-primary-900/10";
                                }

                                return (
                                    <button 
                                        key={idx} 
                                        onClick={() => handleOptionSelect(idx)}
                                        disabled={showResult}
                                        className={btnClass}
                                    >
                                        <div className="flex items-center justify-between">
                                            <span>{option}</span>
                                            {showResult && isCorrect && <CheckCircleIcon className="w-5 h-5 text-green-600" />}
                                            {showResult && isSelected && !isCorrect && <XCircleIcon className="w-5 h-5 text-red-600" />}
                                        </div>
                                    </button>
                                );
                            })}
                        </div>
                    </div>
                )}
            </Card>
        </div>
    );
};

