Here is the implementation plan for **Strategy 4: The Data Economy**.

### Specification

1.  **Database Schema (SQL):**
    *   Create `store_items` table to replace mock data.
    *   Create `user_store_purchases` table to track orders (pending, fulfilled, rejected).
    *   Add columns for purchase metadata (Phone Number, Network) so Admins know where to send the data.
    *   Create RPC `purchase_store_item` to atomically deduct coins and record the request.
    *   Create RPC `process_store_redemption` for Admins to Fulfill (mark done) or Reject (refund coins).

2.  **Frontend: `Store.tsx` Updates:**
    *   Fetch items from the database.
    *   Add a **Purchase Modal**: When clicking "Buy" on the Data Bundle, prompt for **Phone Number** and **Network** (MTN, Airtel, etc.).
    *   **Visuals:** Highlight the Data Bundle card (Gold border/Glow) to draw attention.
    *   **Logic:** Check coin balance. If insufficient, show a CTA: "Not enough coins? Upload a Past Question now to earn 50!"

3.  **Frontend: `FinancialManagement.tsx` Updates:**
    *   Add a new tab: **"Store Redemptions"**.
    *   List pending data requests with the user's provided Phone Number and Network.
    *   Actions: "Mark Sent" (Finalizes it) or "Reject" (Refunds coins).

4.  **Frontend: `Icons.tsx`:**
    *   Add `WifiIcon` for the data bundle.

### SQL Code (Run in Supabase SQL Editor)

```sql
-- 1. Create Store Items Table
CREATE TABLE IF NOT EXISTS public.store_items (
    id uuid DEFAULT gen_random_uuid() PRIMARY KEY,
    name text NOT NULL,
    description text,
    cost integer NOT NULL,
    icon text, -- E.g., 'wifi', 'coffee', 'shirt'
    is_active boolean DEFAULT true,
    created_at timestamp with time zone DEFAULT now()
);

-- 2. Create Purchases Table
CREATE TABLE IF NOT EXISTS public.user_store_purchases (
    id uuid DEFAULT gen_random_uuid() PRIMARY KEY,
    user_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE,
    item_id uuid REFERENCES public.store_items(id) ON DELETE SET NULL,
    item_name text, -- Snapshot in case item is deleted
    cost integer NOT NULL,
    status text DEFAULT 'pending' CHECK (status IN ('pending', 'fulfilled', 'rejected')),
    purchase_metadata jsonb, -- Stores { phoneNumber: "...", network: "..." }
    created_at timestamp with time zone DEFAULT now(),
    processed_at timestamp with time zone
);

-- 3. Seed the Data Bundle Item
INSERT INTO public.store_items (name, description, cost, icon)
VALUES 
('500MB Data Bundle', 'Get 500MB data valid for 2 days. Available for MTN, Airtel, Glo, and 9mobile.', 1000, 'wifi'),
('1GB Data Bundle', 'Get 1GB data valid for 1 week.', 2000, 'wifi'),
('Fellowship T-Shirt', 'Official ACCF Ikole T-Shirt.', 5000, 'shirt');

-- 4. Enable RLS
ALTER TABLE public.store_items ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.user_store_purchases ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Read store items" ON public.store_items FOR SELECT USING (true);
CREATE POLICY "Users view own purchases" ON public.user_store_purchases FOR SELECT USING (auth.uid() = user_id);
CREATE POLICY "Admins view all purchases" ON public.user_store_purchases FOR SELECT USING (
  EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = auth.uid() AND role IN ('admin', 'finance'))
);

-- 5. RPC: Purchase Item (Deduct coins + Record transaction + Create Purchase Request)
CREATE OR REPLACE FUNCTION purchase_store_item(
    p_item_id uuid,
    p_user_id uuid,
    p_metadata jsonb
)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE
    v_cost int;
    v_user_coins int;
    v_item_name text;
BEGIN
    -- Get item details
    SELECT cost, name INTO v_cost, v_item_name FROM public.store_items WHERE id = p_item_id;

    -- Check balance
    SELECT coins INTO v_user_coins FROM public.profiles WHERE id = p_user_id;

    IF v_user_coins < v_cost THEN
        RAISE EXCEPTION 'Insufficient coins';
    END IF;

    -- Deduct Coins
    UPDATE public.profiles SET coins = coins - v_cost WHERE id = p_user_id;

    -- Create Coin Transaction Record (Negative value)
    INSERT INTO public.coin_transactions (user_id, source_type, source_id, coin_amount, status, reason)
    VALUES (p_user_id, 'store_purchase', p_item_id::text, -v_cost, 'approved', 'Purchased: ' || v_item_name);

    -- Create Purchase Request
    INSERT INTO public.user_store_purchases (user_id, item_id, item_name, cost, status, purchase_metadata)
    VALUES (p_user_id, p_item_id, v_item_name, v_cost, 'pending', p_metadata);
END;
$$;

-- 6. RPC: Process Redemption (Admin action)
CREATE OR REPLACE FUNCTION process_store_redemption(
    p_purchase_id uuid,
    p_status text, -- 'fulfilled' or 'rejected'
    p_admin_id uuid
)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE
    v_purchase_record RECORD;
BEGIN
    SELECT * INTO v_purchase_record FROM public.user_store_purchases WHERE id = p_purchase_id;

    IF v_purchase_record.status != 'pending' THEN
        RAISE EXCEPTION 'Request already processed';
    END IF;

    UPDATE public.user_store_purchases 
    SET status = p_status, processed_at = now() 
    WHERE id = p_purchase_id;

    -- If Rejected, Refund Coins
    IF p_status = 'rejected' THEN
        UPDATE public.profiles SET coins = coins + v_purchase_record.cost WHERE id = v_purchase_record.user_id;

        INSERT INTO public.coin_transactions (user_id, source_type, source_id, coin_amount, status, reason)
        VALUES (v_purchase_record.user_id, 'admin_adjustment', p_admin_id::text, v_purchase_record.cost, 'approved', 'Refund for: ' || v_purchase_record.item_name);

        INSERT INTO public.notifications (user_id, type, message)
        VALUES (v_purchase_record.user_id, 'custom', 'Your purchase of ' || v_purchase_record.item_name || ' was rejected and coins refunded.');
    ELSE
        INSERT INTO public.notifications (user_id, type, message)
        VALUES (v_purchase_record.user_id, 'custom', 'Your purchase of ' || v_purchase_record.item_name || ' has been fulfilled! Check your device.');
    END IF;
END;
$$;

-- 7. Update source_type enum to include 'store_purchase' if not exists
-- (Run this block only if you haven't defined the enum strictly, otherwise you might need to alter type)
-- ALTER TYPE public.source_type_enum ADD VALUE IF NOT EXISTS 'store_purchase';
```

### Application Code Updates

