export interface Faculty {
  id: string;
  name: string;
  created_at: string;
}

export interface Department {
  id: string;
  name: string;
  faculty_id: string;
  created_at: string;
}

export interface Course {
  id: string;
  name: string;
  code: string;
  level: number;
  department_id: string | null; // Can be null for general courses
