    id: string;
    quiz_id: string;
    question_text: string;
    options: string[];
    correct_option_index: number;
}

export interface QuizAttempt {
    id: string;
    user_id: string;
    quiz_id: string;
    score: number;
    passed: boolean;
    created_at: string;
}

