    id: string;
    material_id: string;
    created_at: string;
}

export interface MaterialQuizQuestion {
    id: string;
    quiz_id: string;
    question_text: string;
    options: string[];
    correct_option_index: number;
}

export interface MaterialQuizAttempt {
    id: string;
    quiz_id: string;
    user_id: string;
