import React, { useState, useEffect } from 'react';
import Card from '../components/ui/Card';
import { supabase } from '../lib/supabaseClient';
import { useAppContext } from '../context/AppContext';
import { useNotifier } from '../context/NotificationContext';
import type { CoinTransaction, StoreItem } from '../types';
import Button from '../components/ui/Button';
import { WifiIcon, ShoppingCartIcon, CoinIcon, XIcon, CloudUploadIcon } from '../components/ui/Icons';
import { useNavigate } from 'react-router-dom';

const StatusBadge: React.FC<{ status: 'pending' | 'approved' | 'rejected' }> = ({ status }) => {
    const baseClasses = "px-2 py-1 text-xs font-semibold rounded-full capitalize";
    const statusClasses = {
        pending: "bg-yellow-100 text-yellow-800 dark:bg-yellow-900/50 dark:text-yellow-300",
        approved: "bg-green-100 text-green-800 dark:bg-green-900/50 dark:text-green-300",
        rejected: "bg-red-100 text-red-800 dark:bg-red-900/50 dark:text-red-300",
    };
    return <span className={`${baseClasses} ${statusClasses[status]}`}>{status}</span>;
}

const Store: React.FC = () => {
    const { currentUser, refreshCurrentUser } = useAppContext();
    const { addToast } = useNotifier();
    const navigate = useNavigate();

    // Data States
    const [storeItems, setStoreItems] = useState<StoreItem[]>([]);
    const [transactions, setTransactions] = useState<CoinTransaction[]>([]);
    const [loading, setLoading] = useState(true);

    // Purchase Modal States
    const [selectedItem, setSelectedItem] = useState<StoreItem | null>(null);
    const [isPurchaseModalOpen, setIsPurchaseModalOpen] = useState(false);
    const [phoneNumber, setPhoneNumber] = useState(currentUser?.whatsapp || '');
    const [network, setNetwork] = useState('MTN');
    const [purchasing, setPurchasing] = useState(false);

    useEffect(() => {
        const fetchData = async () => {
            if (!supabase || !currentUser) return;
            setLoading(true);

            // 1. Fetch Store Items
            const { data: itemsData, error: itemsError } = await supabase
                .from('store_items')
                .select('*')
                .eq('is_active', true)
                .order('cost', { ascending: true });

            if (itemsError) console.error("Error fetching store items:", itemsError);
            else setStoreItems(itemsData || []);

            // 2. Fetch User Transactions (History)
            const { data: txData, error: txError } = await supabase
                .from('coin_transactions')
                .select('*')
                .eq('user_id', currentUser.id)
                .order('created_at', { ascending: false })
                .limit(20); // Limit history for performance

            if (txError) {
                console.error("Error fetching transactions:", txError);
            } else if (txData) {
                // Enriching transactions would ideally be done via a join in Supabase if RLS allows, 
                // but simpler here since we just want a basic history.
                setTransactions(txData as CoinTransaction[]);
            }

            setLoading(false);
        };

        fetchData();
    }, [currentUser]);

    const handleBuyClick = (item: StoreItem) => {
        setSelectedItem(item);
        setIsPurchaseModalOpen(true);
        // Pre-fill phone number if available
        if (currentUser?.whatsapp) {
            setPhoneNumber(currentUser.whatsapp);
        }
    };

    const handleConfirmPurchase = async () => {
        if (!selectedItem || !supabase || !currentUser) return;

        if (currentUser.coins < selectedItem.cost) {
            addToast("Insufficient coins! Upload more materials to earn.", 'error');
            return;
        }

        // Specific validation for Data Bundles
        if (selectedItem.icon === 'wifi') {
            if (!phoneNumber || !network) {
                addToast("Phone number and network are required for data bundles.", 'error');
                return;
            }
        }

        setPurchasing(true);

        const metadata = selectedItem.icon === 'wifi' 
            ? { phoneNumber, network } 
            : {};

        try {
            const { error } = await supabase.rpc('purchase_store_item', {
                p_item_id: selectedItem.id,
                p_user_id: currentUser.id,
                p_metadata: metadata
            });

            if (error) throw error;

            addToast("Purchase successful! Admin will process your request shortly.", 'success');
            setIsPurchaseModalOpen(false);
            setPhoneNumber(''); 

            // Refresh coin balance and history
            await refreshCurrentUser();
            // Re-fetch transactions (simple inline reload for now)
            const { data: txData } = await supabase
                .from('coin_transactions')
                .select('*')
                .eq('user_id', currentUser.id)
                .order('created_at', { ascending: false })
                .limit(20);
            if (txData) setTransactions(txData as CoinTransaction[]);

        } catch (error: any) {
            console.error("Purchase error:", error);
            addToast(`Purchase failed: ${error.message}`, 'error');
        } finally {
            setPurchasing(false);
        }
    };

    // Helper to render icon based on string stored in DB
    const renderIcon = (iconName: string, className: string = "w-6 h-6") => {
        switch (iconName) {
            case 'wifi': return <WifiIcon className={className} />;
            case 'shirt': return <span className="text-2xl">👕</span>;
            case 'coffee': return <span className="text-2xl">☕</span>;
            default: return <ShoppingCartIcon className={className} />;
        }
    };

    return (
        <div className="space-y-6">
            {/* Header Stats */}
            <div className="flex flex-col sm:flex-row gap-4 justify-between items-center bg-gradient-to-r from-yellow-500 to-amber-600 p-6 rounded-xl text-white shadow-lg">
                <div>
                    <h1 className="text-2xl font-bold">Coin Store</h1>
                    <p className="text-yellow-100 text-sm">Redeem your hard-earned coins for real value.</p>
                </div>
                <div className="flex items-center gap-3 bg-white/20 px-4 py-2 rounded-lg backdrop-blur-sm">
                    <CoinIcon className="w-8 h-8 text-yellow-200" />
                    <div>
                        <p className="text-xs uppercase font-bold text-yellow-100">Balance</p>
                        <p className="text-2xl font-bold">{currentUser?.coins.toLocaleString()}</p>
                    </div>
                </div>
            </div>

            {/* Store Grid */}
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
                {loading ? (
                    <p className="col-span-full text-center py-8">Loading store items...</p>
                ) : storeItems.length > 0 ? (
                    storeItems.map(item => (
                        <Card key={item.id} className={`flex flex-col h-full border-2 transition-all hover:-translate-y-1 hover:shadow-xl ${item.icon === 'wifi' ? 'border-yellow-400 dark:border-yellow-600' : 'border-transparent'}`}>
                            <div className={`p-4 rounded-t-lg flex justify-center items-center h-32 ${item.icon === 'wifi' ? 'bg-yellow-50 dark:bg-yellow-900/20' : 'bg-gray-100 dark:bg-gray-800'}`}>
                                {renderIcon(item.icon, "w-16 h-16 text-gray-600 dark:text-gray-300")}
                            </div>
                            <div className="p-5 flex-grow flex flex-col">
                                {item.icon === 'wifi' && <span className="inline-block px-2 py-1 mb-2 text-xs font-bold text-yellow-700 bg-yellow-100 rounded-full w-fit">HOT DEAL 🔥</span>}
                                <h3 className="text-lg font-bold text-gray-800 dark:text-white">{item.name}</h3>
                                <p className="text-sm text-gray-500 mt-2 flex-grow">{item.description}</p>
                                <div className="mt-4 pt-4 border-t dark:border-gray-700 flex justify-between items-center">
                                    <span className="font-bold text-lg text-primary-600">{item.cost} Coins</span>
                                    <Button size="sm" onClick={() => handleBuyClick(item)} disabled={currentUser ? currentUser.coins < item.cost : true}>
                                        {currentUser && currentUser.coins >= item.cost ? 'Buy Now' : 'Need Coins'}
                                    </Button>
                                </div>
                            </div>
                        </Card>
                    ))
                ) : (
                    <p className="col-span-full text-center text-gray-500">No items available in the store right now.</p>
                )}

                {/* Upload CTA Card */}
                <div onClick={() => navigate('/academics')} className="cursor-pointer bg-gradient-to-br from-primary-600 to-primary-800 rounded-xl shadow-md p-6 text-white flex flex-col justify-center items-center text-center transition-transform hover:scale-105">
                    <CloudUploadIcon className="w-12 h-12 mb-3 text-primary-200" />
                    <h3 className="font-bold text-xl">Need More Coins?</h3>
                    <p className="text-primary-100 text-sm mt-2">Upload past questions or notes to earn 50-100 coins instantly!</p>
                    <button className="mt-4 bg-white text-primary-700 font-bold py-2 px-4 rounded-full text-sm hover:bg-primary-50">
                        Upload Now
                    </button>
                </div>
            </div>

            {/* Transaction History */}
            <Card title="Recent Transactions">
                {transactions.length > 0 ? (
                    <div className="flow-root">
                        <ul role="list" className="divide-y divide-gray-200 dark:divide-gray-700">
                            {transactions.map(tx => (
                                <li key={tx.id} className="py-4">
                                    <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-2">
                                        <div className="flex-1 min-w-0">
                                            <p className="font-medium text-gray-900 truncate dark:text-white">
                                                {tx.reason || (tx.source_type === 'store_purchase' ? 'Store Purchase' : 'Activity Reward')}
                                            </p>
                                            <p className="text-sm text-gray-500 truncate dark:text-gray-400">
                                                {new Date(tx.created_at).toLocaleString()}
                                            </p>
                                        </div>
                                        <div className="flex items-center justify-between sm:justify-end gap-4 mt-2 sm:mt-0">
                                            <p className={`font-semibold ${tx.coin_amount > 0 ? 'text-green-600' : 'text-red-500'}`}>
                                                {tx.coin_amount > 0 ? '+' : ''}{tx.coin_amount} Coins
                                            </p>
                                            {tx.status && <StatusBadge status={tx.status} />}
                                        </div>
                                    </div>
                                </li>
                            ))}
                        </ul>
                    </div>
                ) : (
                    <p className="text-gray-500 py-4 text-center">No transaction history yet.</p>
                )}
            </Card>

            {/* Purchase Modal */}
            {isPurchaseModalOpen && selectedItem && (
                <div className="fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-4 animate-fade-in-up" style={{ animationDuration: '200ms' }}>
                    <Card className="w-full max-w-md relative">
                        <button onClick={() => setIsPurchaseModalOpen(false)} className="absolute top-4 right-4 text-gray-400 hover:text-gray-600">
                            <XIcon className="w-6 h-6" />
                        </button>

                        <div className="text-center mb-6">
                            <div className="w-16 h-16 bg-yellow-100 rounded-full flex items-center justify-center mx-auto mb-3">
                                {renderIcon(selectedItem.icon, "w-8 h-8 text-yellow-600")}
                            </div>
                            <h2 className="text-xl font-bold">Confirm Purchase</h2>
                            <p className="text-gray-500">{selectedItem.name}</p>
                            <p className="text-2xl font-bold text-primary-600 mt-2">{selectedItem.cost} Coins</p>
                        </div>

                        {selectedItem.icon === 'wifi' && (
                            <div className="space-y-4 mb-6">
                                <div>
                                    <label className="block text-sm font-medium mb-1">Phone Number</label>
                                    <input 
                                        type="tel" 
                                        value={phoneNumber} 
                                        onChange={(e) => setPhoneNumber(e.target.value)}
                                        className="w-full bg-gray-50 dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-md p-2"
                                        placeholder="080..."
                                    />
                                </div>
                                <div>
                                    <label className="block text-sm font-medium mb-1">Network</label>
                                    <select 
                                        value={network} 
                                        onChange={(e) => setNetwork(e.target.value)}
                                        className="w-full bg-gray-50 dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-md p-2"
                                    >
                                        <option value="MTN">MTN</option>
                                        <option value="Airtel">Airtel</option>
                                        <option value="Glo">Glo</option>
                                        <option value="9mobile">9mobile</option>
                                    </select>
                                </div>
                                <p className="text-xs text-yellow-600 bg-yellow-50 p-2 rounded">
                                    Note: Data will be sent to this number within 24 hours.
                                </p>
                            </div>
                        )}

                        <div className="flex gap-3">
                            <Button variant="ghost" className="flex-1" onClick={() => setIsPurchaseModalOpen(false)}>Cancel</Button>
                            <Button className="flex-1" onClick={handleConfirmPurchase} disabled={purchasing}>
                                {purchasing ? 'Processing...' : 'Confirm Buy'}
                            </Button>
                        </div>
                    </Card>
                </div>
            )}
        </div>
    );
};

export default Store;

import React, { useState, useEffect, useCallback } from 'react';
import { supabase } from '../lib/supabaseClient';
import Card from '../components/ui/Card';
import Button from '../components/ui/Button';
import type { Donation, StorePurchase } from '../types';
import Avatar from '../components/auth/Avatar';
import { ChatIcon, CheckCircleIcon, XCircleIcon, ShoppingCartIcon, WifiIcon } from '../components/ui/Icons';
import { useNotifier } from '../context/NotificationContext';
import { useAppContext } from '../context/AppContext';

const FinancialManagement: React.FC = () => {
    const { currentUser } = useAppContext();
    const { addToast, showConfirm } = useNotifier();

    // Donation State
    const [donations, setDonations] = useState<Donation[]>([]);
    const [loadingDonations, setLoadingDonations] = useState(true);
    const [activeTab, setActiveTab] = useState<'donations' | 'redemptions'>('donations');

    // Store Redemptions State
    const [redemptions, setRedemptions] = useState<StorePurchase[]>([]);
    const [loadingRedemptions, setLoadingRedemptions] = useState(true);

    const fetchDonations = useCallback(async () => {
        if (!supabase) return;
        setLoadingDonations(true);
        const { data, error } = await supabase
            .from('donations')
            .select('*, profiles(full_name, avatar_url, whatsapp)')
            .order('created_at', { ascending: false });

        if (error) {
            addToast('Error fetching donations: ' + error.message, 'error');
        } else {
            setDonations(data as Donation[] || []);
        }
        setLoadingDonations(false);
    }, [addToast]);

    const fetchRedemptions = useCallback(async () => {
        if (!supabase) return;
        setLoadingRedemptions(true);
        // We use a join, but user_store_purchases links to profiles via user_id
        const { data, error } = await supabase
            .from('user_store_purchases')
            .select('*, profiles:user_id(full_name, avatar_url, whatsapp)')
            .order('created_at', { ascending: false });

        if (error) {
            addToast('Error fetching redemptions: ' + error.message, 'error');
        } else {
            setRedemptions(data as any[] || []);
        }
        setLoadingRedemptions(false);
    }, [addToast]);

    useEffect(() => {
        if (activeTab === 'donations') fetchDonations();
        else fetchRedemptions();
    }, [activeTab, fetchDonations, fetchRedemptions]);

    // --- Real-time Subscription ---
    useEffect(() => {
        if (!supabase) return;
        const channel = supabase
            .channel('financial-realtime')
            .on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'donations' }, () => {
                addToast('New donation recorded.', 'info');
                if (activeTab === 'donations') fetchDonations();
            })
            .on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'user_store_purchases' }, () => {
                addToast('New store redemption request.', 'info');
                if (activeTab === 'redemptions') fetchRedemptions();
            })
            .subscribe();

        return () => {
            supabase.removeChannel(channel);
        };
    }, [activeTab, fetchDonations, fetchRedemptions]);

    // --- Donation Logic ---
    const handleUpdateDonationStatus = async (donationId: string, status: 'confirmed' | 'rejected') => {
        if (!supabase || !currentUser) return;
        const { error } = await supabase.rpc('update_donation_status', {
            p_donation_id: donationId,
            p_new_status: status,
            p_admin_id: currentUser.id
        });
        if (error) {
            addToast('Error updating status: ' + error.message, 'error');
        } else {
            addToast(`Donation status updated to ${status}.`, 'success');
            fetchDonations();
        }
    };

    const handleSendReminder = async (userId: string, name: string, amount: number, fund: string) => {
        if (!supabase || !currentUser) return;
        const message = `Hi ${name}, friendly reminder regarding your pledge of ₦${amount.toLocaleString()} for "${fund}". Please send proof of payment when ready!`;
        const { error } = await supabase.from('messages').insert({ sender_id: currentUser.id, recipient_id: userId, text: message });
        if (error) addToast('Failed to send reminder.', 'error');
        else addToast('Reminder sent.', 'success');
    };

    // --- Redemption Logic ---
    const handleProcessRedemption = async (purchase: StorePurchase, status: 'fulfilled' | 'rejected') => {
        if (!supabase || !currentUser) return;

        const action = status === 'fulfilled' ? 'Fulfill (Send Data)' : 'Reject (Refund Coins)';

        showConfirm(`Are you sure you want to ${action}?`, async () => {
            const { error } = await supabase.rpc('process_store_redemption', {
                p_purchase_id: purchase.id,
                p_status: status,
                p_admin_id: currentUser.id
            });

            if (error) {
                addToast('Error processing request: ' + error.message, 'error');
            } else {
                addToast(`Request ${status}. User has been notified.`, 'success');
                fetchRedemptions();
            }
        });
    };

    const StatusBadge = ({ status }: { status: string }) => {
        const styles: Record<string, string> = {
            pending: 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900/50 dark:text-yellow-300',
            confirmed: 'bg-green-100 text-green-800 dark:bg-green-900/50 dark:text-green-300',
            fulfilled: 'bg-green-100 text-green-800 dark:bg-green-900/50 dark:text-green-300',
            rejected: 'bg-red-100 text-red-800 dark:bg-red-900/50 dark:text-red-300',
        };
        return <span className={`px-2 py-1 text-xs font-semibold rounded-full capitalize ${styles[status] || 'bg-gray-100 text-gray-800'}`}>{status}</span>;
    };

    return (
         <div className="space-y-6">
            <h1 className="text-2xl sm:text-3xl font-bold text-gray-800 dark:text-white">Financial Management</h1>

            <div className="border-b dark:border-gray-700">
                <nav className="-mb-px flex space-x-6">
                    <button
                        onClick={() => setActiveTab('donations')}
                        className={`py-4 px-1 border-b-2 font-medium text-sm ${activeTab === 'donations' ? 'border-primary-500 text-primary-600' : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'}`}
                    >
                        Donations
                    </button>
                    <button
                        onClick={() => setActiveTab('redemptions')}
                        className={`py-4 px-1 border-b-2 font-medium text-sm ${activeTab === 'redemptions' ? 'border-primary-500 text-primary-600' : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'}`}
                    >
                        Store Redemptions
                    </button>
                </nav>
            </div>

            {activeTab === 'donations' ? (
                <Card title="Donation Tracking">
                    {loadingDonations ? <p>Loading...</p> : donations.length === 0 ? <p className="text-gray-500">No donations found.</p> : (
                        <ul className="space-y-3">
                            {donations.map(d => (
                                <li key={d.id} className="bg-gray-50 dark:bg-gray-800 p-4 rounded-lg">
                                    <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3">
                                        <div className="flex items-center gap-3">
                                            <Avatar src={d.profiles?.avatar_url} alt="" />
                                            <div>
                                                <p className="font-semibold">{d.profiles?.full_name}</p>
                                                <p className="text-sm text-gray-500">Pledged: ₦{d.amount.toLocaleString()} for {d.fund_name}</p>
                                                <p className="text-xs text-gray-400">{new Date(d.created_at).toLocaleString()}</p>
                                            </div>
                                        </div>
                                        <div className="flex items-center gap-2 self-end sm:self-center">
                                            {d.status === 'pending' ? (
                                                <>
                                                    <Button size="sm" variant="ghost" onClick={() => handleSendReminder(d.user_id, d.profiles?.full_name || '', d.amount, d.fund_name)}><ChatIcon className="w-4 h-4" /></Button>
                                                    <Button size="sm" variant="outline" className="text-red-600 border-red-600 hover:bg-red-50" onClick={() => handleUpdateDonationStatus(d.id, 'rejected')}><XCircleIcon className="w-4 h-4" /></Button>
                                                    <Button size="sm" onClick={() => handleUpdateDonationStatus(d.id, 'confirmed')}><CheckCircleIcon className="w-4 h-4" /></Button>
                                                </>
                                            ) : <StatusBadge status={d.status} />}
                                        </div>
                                    </div>
                                </li>
                            ))}
                        </ul>
                    )}
                </Card>
            ) : (
                <Card title="Store Redemptions">
                    {loadingRedemptions ? <p>Loading...</p> : redemptions.length === 0 ? <p className="text-gray-500">No requests found.</p> : (
                        <ul className="space-y-3">
                            {redemptions.map(req => (
                                <li key={req.id} className="bg-gray-50 dark:bg-gray-800 p-4 rounded-lg border border-gray-200 dark:border-gray-700">
                                    <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                                        <div className="flex items-start gap-3">
                                            <div className="bg-yellow-100 p-2 rounded-full mt-1"><ShoppingCartIcon className="w-5 h-5 text-yellow-700" /></div>
                                            <div>
                                                <p className="font-bold text-gray-800 dark:text-white">{req.item_name} <span className="font-normal text-gray-500">({req.cost} coins)</span></p>
                                                <div className="flex items-center gap-2 mt-1">
                                                    <Avatar src={req.profiles?.avatar_url} alt="" size="sm" />
                                                    <span className="text-sm font-medium">{req.profiles?.full_name}</span>
                                                </div>

                                                {/* Display Metadata (Phone/Network) if available */}
                                                {req.purchase_metadata && (
                                                    <div className="mt-2 text-sm bg-white dark:bg-gray-700 p-2 rounded border dark:border-gray-600 inline-block">
                                                        {req.purchase_metadata.network && (
                                                            <p className="flex items-center gap-1"><strong>Network:</strong> {req.purchase_metadata.network}</p>
                                                        )}
                                                        {req.purchase_metadata.phoneNumber && (
                                                            <p className="flex items-center gap-1"><strong>Phone:</strong> {req.purchase_metadata.phoneNumber}</p>
                                                        )}
                                                    </div>
                                                )}
                                                <p className="text-xs text-gray-400 mt-1">{new Date(req.created_at).toLocaleString()}</p>
                                            </div>
                                        </div>

                                        <div className="flex items-center gap-2 self-end md:self-center">
                                            {req.status === 'pending' ? (
                                                <>
                                                    <Button size="sm" variant="outline" className="text-red-600 border-red-600 hover:bg-red-50" onClick={() => handleProcessRedemption(req, 'rejected')}>
                                                        Reject & Refund
                                                    </Button>
                                                    <Button size="sm" onClick={() => handleProcessRedemption(req, 'fulfilled')}>
                                                        Mark Sent
                                                    </Button>
                                                </>
                                            ) : <StatusBadge status={req.status} />}
                                        </div>
                                    </div>
                                </li>
                            ))}
                        </ul>
                    )}
                </Card>
            )}
        </div>
    );
};

export default FinancialManagement;

