### SQL for Database Setup

Run the following SQL in your Supabase SQL Editor to create the missing tables and functions:

```sql
-- Store Items Table
CREATE TABLE IF NOT EXISTS public.store_items (
    id uuid DEFAULT gen_random_uuid() PRIMARY KEY,
    name text NOT NULL,
    description text,
    cost integer NOT NULL,
    icon text, -- 'wifi', 'shirt', 'coffee' etc
    is_active boolean DEFAULT true,
    created_at timestamp with time zone DEFAULT now()
);

-- Purchases Table
CREATE TABLE IF NOT EXISTS public.user_store_purchases (
    id uuid DEFAULT gen_random_uuid() PRIMARY KEY,
    user_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE NOT NULL,
    item_id uuid REFERENCES public.store_items(id) ON DELETE SET NULL,
    item_name text NOT NULL,
    cost integer NOT NULL,
    status text CHECK (status IN ('pending', 'fulfilled', 'rejected')) DEFAULT 'pending',
    purchase_metadata jsonb, -- e.g. { phoneNumber: "...", network: "..." }
    created_at timestamp with time zone DEFAULT now()
);

-- RLS
ALTER TABLE public.store_items ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public view active items" ON public.store_items FOR SELECT USING (is_active = true);

ALTER TABLE public.user_store_purchases ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Users view own purchases" ON public.user_store_purchases FOR SELECT USING (auth.uid() = user_id);
-- We won't allow direct insert on purchases via API, we'll use RPC for safety (coin deduction)

-- RPC to purchase item
CREATE OR REPLACE FUNCTION purchase_store_item(p_item_id uuid, p_user_id uuid, p_metadata jsonb DEFAULT '{}'::jsonb)
RETURNS void AS $$
DECLARE
    v_item_cost integer;
    v_user_coins integer;
    v_item_name text;
BEGIN
    -- 1. Get Item Details
    SELECT cost, name INTO v_item_cost, v_item_name FROM public.store_items WHERE id = p_item_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Item not found';
    END IF;

    -- 2. Get User Coins
    SELECT coins INTO v_user_coins FROM public.profiles WHERE id = p_user_id;
    IF v_user_coins < v_item_cost THEN
        RAISE EXCEPTION 'Insufficient coins';
    END IF;

    -- 3. Deduct Coins
    UPDATE public.profiles SET coins = coins - v_item_cost WHERE id = p_user_id;

    -- 4. Record Transaction (Coin History)
    INSERT INTO public.coin_transactions (user_id, source_type, source_id, coin_amount, status, reason)
    VALUES (p_user_id, 'store_purchase', p_item_id, -v_item_cost, 'approved', 'Purchased ' || v_item_name);

    -- 5. Record Purchase Request
    INSERT INTO public.user_store_purchases (user_id, item_id, item_name, cost, purchase_metadata, status)
    VALUES (p_user_id, p_item_id, v_item_name, v_item_cost, p_metadata, 'pending');

END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Insert some dummy store items if empty
INSERT INTO public.store_items (name, description, cost, icon)
SELECT '1GB Data Bundle', 'Valid for 30 days. Available for MTN, Airtel, Glo, 9mobile.', 500, 'wifi'
WHERE NOT EXISTS (SELECT 1 FROM public.store_items WHERE icon = 'wifi');

INSERT INTO public.store_items (name, description, cost, icon)
SELECT 'Fellowship T-Shirt', 'Branded cotton t-shirt. Available in various sizes.', 2500, 'shirt'
WHERE NOT EXISTS (SELECT 1 FROM public.store_items WHERE icon = 'shirt');

INSERT INTO public.store_items (name, description, cost, icon)
SELECT 'Coffee with President', '30 mins chat with the fellowship president.', 1000, 'coffee'
WHERE NOT EXISTS (SELECT 1 FROM public.store_items WHERE icon = 'coffee');

