This error occurs because the `source_id` column in your `coin_transactions` table is defined as a `UUID` type, but the application is trying to insert a value that isn't strictly a UUID (or the function needs an explicit cast).

To support all features of your app (including Onboarding tasks which use text IDs like "profile_completion"), the `source_id` column should be of type `TEXT`, not `UUID`.

Run this SQL code in your Supabase SQL Editor to fix the table structure and update the purchase function:

```sql
-- 1. Modify the coin_transactions table
-- Change source_id from UUID to TEXT to allow both UUIDs and string IDs (like 'profile_completion')
ALTER TABLE public.coin_transactions
ALTER COLUMN source_id TYPE text;

-- 2. Update the purchase_store_item function
-- This updates the function to explicitly cast the item UUID to text during insertion
CREATE OR REPLACE FUNCTION purchase_store_item(p_item_id uuid, p_user_id uuid, p_metadata jsonb DEFAULT '{}'::jsonb)
RETURNS void AS $$
DECLARE
    v_item_cost integer;
    v_user_coins integer;
    v_item_name text;
BEGIN
    -- 1. Get Item Details
    SELECT cost, name INTO v_item_cost, v_item_name FROM public.store_items WHERE id = p_item_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Item not found';
    END IF;

    -- 2. Get User Coins
    SELECT coins INTO v_user_coins FROM public.profiles WHERE id = p_user_id;
    IF v_user_coins < v_item_cost THEN
        RAISE EXCEPTION 'Insufficient coins';
    END IF;

    -- 3. Deduct Coins
    UPDATE public.profiles SET coins = coins - v_item_cost WHERE id = p_user_id;

    -- 4. Record Transaction (Coin History)
    -- We explicitly cast p_item_id to text here (p_item_id::text)
    INSERT INTO public.coin_transactions (user_id, source_type, source_id, coin_amount, status, reason)
    VALUES (p_user_id, 'store_purchase', p_item_id::text, -v_item_cost, 'approved', 'Purchased ' || v_item_name);

    -- 5. Record Purchase Request
    INSERT INTO public.user_store_purchases (user_id, item_id, item_name, cost, purchase_metadata, status)
    VALUES (p_user_id, p_item_id, v_item_name, v_item_cost, p_metadata, 'pending');

END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

