import React, { useState, useEffect, useCallback, useRef } from 'react';
import Card from '../components/ui/Card';
import Button from '../components/ui/Button';
import { StarIcon, PlayIcon, StopIcon, FireIcon, TrophyIcon } from '../components/ui/Icons';
import { useNotifier } from '../context/NotificationContext';

// Game Configuration
const GRID_SIZE = 9; // 3x3
const GAME_DURATION = 60; // seconds
const BASE_SPAWN_RATE = 1000; // ms
const MIN_SPAWN_RATE = 400; // ms

// Items
const GOOD_ITEMS = [
    { text: 'Joy', color: 'bg-yellow-400' },
    { text: 'Peace', color: 'bg-blue-400' },
    { text: 'Love', color: 'bg-red-400' },
    { text: 'Faith', color: 'bg-green-400' },
    { text: 'Kindness', color: 'bg-pink-400' },
];

const BAD_ITEMS = [
    { text: 'Fear', color: 'bg-gray-600' },
    { text: 'Sin', color: 'bg-gray-800' },
    { text: 'Envy', color: 'bg-purple-800' },
    { text: 'Pride', color: 'bg-red-900' },
];

interface ActiveCell {
    id: number;
    type: 'good' | 'bad';
    content: { text: string; color: string };
    expiresAt: number;
}

const GameCenter: React.FC = () => {
    const { addToast } = useNotifier();

    // Game State
    const [isPlaying, setIsPlaying] = useState(false);
    const [score, setScore] = useState(0);
    const [timeLeft, setTimeLeft] = useState(GAME_DURATION);
    const [combo, setCombo] = useState(1);
    const [highScore, setHighScore] = useState(0);

    // Grid State
    const [activeCells, setActiveCells] = useState<Map<number, ActiveCell>>(new Map());
    const [floatingTexts, setFloatingTexts] = useState<{id: number, text: string, x: number, y: number, color: string}[]>([]);

    // Refs for intervals/timeouts
    const gameLoopRef = useRef<number | null>(null);
    const spawnTimerRef = useRef<number | null>(null);
    const spawnRateRef = useRef(BASE_SPAWN_RATE);

    // Load High Score
    useEffect(() => {
        const saved = localStorage.getItem('spirit-blitz-highscore');
        if (saved) setHighScore(parseInt(saved, 10));
    }, []);

    // Game Loop (Timer)
    useEffect(() => {
        if (isPlaying && timeLeft > 0) {
            gameLoopRef.current = window.setInterval(() => {
                setTimeLeft(prev => prev - 1);
                // Increase difficulty
                if (timeLeft % 10 === 0 && spawnRateRef.current > MIN_SPAWN_RATE) {
                    spawnRateRef.current -= 100;
                }
            }, 1000);
        } else if (timeLeft <= 0) {
            endGame();
        }

        return () => {
            if (gameLoopRef.current) clearInterval(gameLoopRef.current);
        };
    }, [isPlaying, timeLeft]);

    // Spawning Logic
    const spawnItem = useCallback(() => {
        if (!isPlaying) return;

        setActiveCells(prev => {
            const newMap = new Map<number, ActiveCell>(prev);

            // Remove expired items
            const now = Date.now();
            Array.from(newMap.entries()).forEach(([key, val]) => {
                if (val.expiresAt < now) newMap.delete(key);
            });

            // Try to spawn new item
            const availableIndices = Array.from({ length: GRID_SIZE }, (_, i) => i).filter(i => !newMap.has(i));

            if (availableIndices.length > 0) {
                const index = availableIndices[Math.floor(Math.random() * availableIndices.length)];
                const isBad = Math.random() < 0.3; // 30% chance of bad item
                const content = isBad 
                    ? BAD_ITEMS[Math.floor(Math.random() * BAD_ITEMS.length)]
                    : GOOD_ITEMS[Math.floor(Math.random() * GOOD_ITEMS.length)];

                newMap.set(index, {
                    id: Math.random(),
                    type: isBad ? 'bad' : 'good',
                    content,
                    expiresAt: Date.now() + 2000 // 2 seconds to click
                });
            }
            return newMap;
        });

        // Schedule next spawn
        spawnTimerRef.current = window.setTimeout(spawnItem, spawnRateRef.current);
    }, [isPlaying]);

    useEffect(() => {
        if (isPlaying) {
            spawnItem();
        }
        return () => {
            if (spawnTimerRef.current) clearTimeout(spawnTimerRef.current);
        };
    }, [isPlaying, spawnItem]);

    const startGame = () => {
        setIsPlaying(true);
        setScore(0);
        setTimeLeft(GAME_DURATION);
        setCombo(1);
        setActiveCells(new Map());
        spawnRateRef.current = BASE_SPAWN_RATE;
        setFloatingTexts([]);
    };

    const endGame = () => {
        setIsPlaying(false);
        if (spawnTimerRef.current) clearTimeout(spawnTimerRef.current);
        if (gameLoopRef.current) clearInterval(gameLoopRef.current);

        if (score > highScore) {
            setHighScore(score);
            localStorage.setItem('spirit-blitz-highscore', score.toString());
            addToast(`New High Score: ${score}!`, 'success');
        } else {
            addToast(`Game Over! Score: ${score}`, 'info');
        }
    };

    const handleTap = (index: number, e: React.MouseEvent) => {
        if (!isPlaying) return;

        const cell = activeCells.get(index);

        // Calculate click position relative to the grid container for floating text
        const rect = (e.target as HTMLElement).getBoundingClientRect();
        // Approximate center if needed, or use click coordinates
        // Using fixed offset for simplicity in grid

        if (cell) {
            if (cell.type === 'good') {
                const points = 10 * combo;
                setScore(prev => prev + points);
                setCombo(prev => Math.min(prev + 1, 5)); // Cap combo at 5x
                addFloatingText(index, `+${points}`, 'text-green-500');
            } else {
                setScore(prev => Math.max(0, prev - 20));
                setCombo(1); // Reset combo
                addFloatingText(index, `-20`, 'text-red-500');
                // Visual shake effect could go here
            }
            // Remove the clicked cell
            setActiveCells(prev => {
                const newMap = new Map(prev);
                newMap.delete(index);
                return newMap;
            });
        } else {
            // Miss click - penalty?
            // setScore(prev => Math.max(0, prev - 5));
            // setCombo(1);
        }
    };

    const addFloatingText = (index: number, text: string, color: string) => {
        const id = Date.now();
        // Simple positioning logic: based on grid index
        // This is a simplified visual representation
        setFloatingTexts(prev => [...prev, { id, text, x: index, y: 0, color }]);
        setTimeout(() => {
            setFloatingTexts(prev => prev.filter(ft => ft.id !== id));
        }, 800);
    };

    return (
        <div className="space-y-6 max-w-lg mx-auto">
            <h1 className="text-3xl font-bold text-center text-gray-800 dark:text-white flex items-center justify-center gap-2">
                <FireIcon className="w-8 h-8 text-orange-500" /> Spirit Blitz
            </h1>

            <Card className="relative overflow-hidden">
                {/* HUD */}
                <div className="flex justify-between items-center mb-4 text-sm font-bold">
                    <div className="flex flex-col items-center">
                        <span className="text-gray-500 uppercase text-xs">Score</span>
                        <span className="text-2xl text-primary-600">{score}</span>
                    </div>
                    <div className="flex flex-col items-center">
                        <span className="text-gray-500 uppercase text-xs">Time</span>
                        <span className={`text-2xl ${timeLeft < 10 ? 'text-red-500 animate-pulse' : 'text-gray-800 dark:text-gray-200'}`}>
                            {timeLeft}s
                        </span>
                    </div>
                    <div className="flex flex-col items-center">
                        <span className="text-gray-500 uppercase text-xs">Combo</span>
                        <span className="text-2xl text-yellow-500">x{combo}</span>
                    </div>
                </div>

                {/* Game Grid */}
                <div className="grid grid-cols-3 gap-3 aspect-square bg-gray-100 dark:bg-gray-800 p-3 rounded-xl relative select-none">
                    {Array.from({ length: GRID_SIZE }).map((_, i) => {
                        const cell = activeCells.get(i);
                        return (
                            <div
                                key={i}
                                onClick={(e) => handleTap(i, e)}
                                className={`rounded-xl flex items-center justify-center text-center font-bold text-white shadow-md transition-all duration-100 active:scale-95 cursor-pointer relative overflow-hidden
                                    ${cell ? cell.content.color : 'bg-white dark:bg-gray-700 opacity-50'}
                                    ${cell ? 'scale-100 animate-bounce' : 'scale-95'}
                                `}
                            >
                                {cell && (
                                    <span className="text-sm md:text-base pointer-events-none drop-shadow-md">
                                        {cell.content.text}
                                    </span>
                                )}

                                {/* Floating Text for this cell */}
                                {floatingTexts.filter(ft => ft.x === i).map(ft => (
                                    <div 
                                        key={ft.id}
                                        className={`absolute inset-0 flex items-center justify-center text-2xl font-black ${ft.color} animate-fade-in-up`}
                                        style={{ animationDuration: '800ms', pointerEvents: 'none' }}
                                    >
                                        {ft.text}
                                    </div>
                                ))}
                            </div>
                        );
                    })}

                    {!isPlaying && timeLeft === GAME_DURATION && (
                        <div className="absolute inset-0 bg-black/40 backdrop-blur-sm flex flex-col items-center justify-center rounded-xl z-10">
                            <p className="text-white text-center mb-4 px-4 font-medium">
                                Tap the <span className="text-green-300">Fruits of the Spirit</span>.<br/>
                                Avoid the <span className="text-red-300">Works of Flesh</span>!
                            </p>
                            <Button size="lg" onClick={startGame} className="animate-pulse shadow-xl border-2 border-white/20">
                                <PlayIcon className="w-6 h-6 mr-2" /> Start Game
                            </Button>
                        </div>
                    )}

                    {!isPlaying && timeLeft <= 0 && (
                        <div className="absolute inset-0 bg-black/60 backdrop-blur-md flex flex-col items-center justify-center rounded-xl z-10">
                            <h2 className="text-3xl font-bold text-white mb-2">Time's Up!</h2>
                            <p className="text-xl text-yellow-300 font-bold mb-6">Final Score: {score}</p>
                            <Button size="lg" onClick={startGame}>
                                Play Again
                            </Button>
                        </div>
                    )}
                </div>
            </Card>

            <div className="flex justify-between items-center px-4">
                <div className="flex items-center gap-2 text-gray-500 dark:text-gray-400">
                    <TrophyIcon className="w-5 h-5 text-yellow-500" />
                    <span className="font-semibold">Best: {highScore}</span>
                </div>
                {isPlaying && (
                    <Button variant="secondary" size="sm" onClick={endGame} className="text-red-500 bg-red-50 hover:bg-red-100 dark:bg-red-900/20">
                        <StopIcon className="w-4 h-4 mr-1" /> End Game
                    </Button>
                )}
            </div>
        </div>
    );
};

export default GameCenter;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import Card from '../components/ui/Card';
import Button from '../components/ui/Button';
import { StarIcon, PlayIcon, StopIcon, FireIcon, TrophyIcon, ClockIcon, BookOpenIcon } from '../components/ui/Icons';
