// Game Configuration
const GRID_SIZE = 9; // 3x3
const GAME_DURATION = 60; // seconds
const BASE_SPAWN_RATE = 1000; // ms
const MIN_SPAWN_RATE = 400; // ms
const DAILY_ACCESS_LIMIT_MS = 10 * 60 * 1000; // 10 minutes in milliseconds

// Items
const GOOD_ITEMS = [
    { text: 'Joy', color: 'bg-yellow-400' },
    { text: 'Peace', color: 'bg-blue-400' },
    { text: 'Love', color: 'bg-red-400' },
    { text: 'Faith', color: 'bg-green-400' },
    { text: 'Kindness', color: 'bg-pink-400' },
];

const BAD_ITEMS = [
    { text: 'Fear', color: 'bg-gray-600' },
    { text: 'Sin', color: 'bg-gray-800' },
    { text: 'Envy', color: 'bg-purple-800' },
    { text: 'Pride', color: 'bg-red-900' },
];

interface ActiveCell {
    id: number;
    type: 'good' | 'bad';
    content: { text: string; color: string };
    expiresAt: number;
}

const GameCenter: React.FC = () => {
    const { addToast } = useNotifier();
    const navigate = useNavigate();

    // Session State
    const [sessionState, setSessionState] = useState<'checking' | 'active' | 'expired'>('checking');
    const [sessionTimeLeft, setSessionTimeLeft] = useState<number>(0);

    // Game State
    const [isPlaying, setIsPlaying] = useState(false);
    const [score, setScore] = useState(0);
    const [timeLeft, setTimeLeft] = useState(GAME_DURATION);
    const [combo, setCombo] = useState(1);
    const [highScore, setHighScore] = useState(0);

    // Grid State
    const [activeCells, setActiveCells] = useState<Map<number, ActiveCell>>(new Map());
    const [floatingTexts, setFloatingTexts] = useState<{id: number, text: string, x: number, y: number, color: string}[]>([]);

    // Refs for intervals/timeouts
    const gameLoopRef = useRef<number | null>(null);
    const spawnTimerRef = useRef<number | null>(null);
    const spawnRateRef = useRef(BASE_SPAWN_RATE);

    // --- SESSION MANAGEMENT LOGIC ---
    useEffect(() => {
        const checkSession = () => {
            const now = Date.now();
            const today = new Date().toDateString(); // "Mon Jul 28 2025"
            const storageKey = 'accf_game_session_v1';

            let session = null;
            try {
                const stored = localStorage.getItem(storageKey);
                if (stored) session = JSON.parse(stored);
            } catch(e) {
                console.error("Error parsing game session", e);
            }

            if (!session || session.date !== today) {
                // New daily session
                const expiresAt = now + DAILY_ACCESS_LIMIT_MS;
                const newSession = { date: today, expiresAt };
                localStorage.setItem(storageKey, JSON.stringify(newSession));
                setSessionState('active');
                setSessionTimeLeft(DAILY_ACCESS_LIMIT_MS);
            } else {
                // Existing session for today
                if (now >= session.expiresAt) {
                    setSessionState('expired');
                    setSessionTimeLeft(0);
                    if (isPlaying) {
                        endGame(true); // Force end if playing
                    }
                } else {
                    setSessionState('active');
                    setSessionTimeLeft(session.expiresAt - now);
                }
            }
        };

        // Check immediately
        checkSession();

        // Check every second to update timer and lock if expired
        const interval = setInterval(checkSession, 1000);
        return () => clearInterval(interval);
    }, [isPlaying]); // Depend on isPlaying to force-stop correctly

    // Format milliseconds to MM:SS
    const formatSessionTime = (ms: number) => {
        const totalSeconds = Math.max(0, Math.floor(ms / 1000));
        const minutes = Math.floor(totalSeconds / 60);
        const seconds = totalSeconds % 60;
        return `${minutes}m ${seconds}s`;
    };

    // Load High Score
    useEffect(() => {
        const saved = localStorage.getItem('spirit-blitz-highscore');
        if (saved) setHighScore(parseInt(saved, 10));
    }, []);

    // Game Loop (Timer)
    useEffect(() => {
        if (isPlaying && timeLeft > 0) {
            gameLoopRef.current = window.setInterval(() => {
                setTimeLeft(prev => prev - 1);
                // Increase difficulty
                if (timeLeft % 10 === 0 && spawnRateRef.current > MIN_SPAWN_RATE) {
                    spawnRateRef.current -= 100;
                }
            }, 1000);
        } else if (timeLeft <= 0 && isPlaying) {
            endGame();
        }

        return () => {
            if (gameLoopRef.current) clearInterval(gameLoopRef.current);
        };
    }, [isPlaying, timeLeft]);

    // Spawning Logic
    const spawnItem = useCallback(() => {
        if (!isPlaying) return;

        setActiveCells(prev => {
            const newMap = new Map<number, ActiveCell>(prev);

            // Remove expired items
            const now = Date.now();
            Array.from(newMap.entries()).forEach(([key, val]) => {
                if (val.expiresAt < now) newMap.delete(key);
            });

            // Try to spawn new item
            const availableIndices = Array.from({ length: GRID_SIZE }, (_, i) => i).filter(i => !newMap.has(i));

            if (availableIndices.length > 0) {
                const index = availableIndices[Math.floor(Math.random() * availableIndices.length)];
                const isBad = Math.random() < 0.3; // 30% chance of bad item
                const content = isBad 
                    ? BAD_ITEMS[Math.floor(Math.random() * BAD_ITEMS.length)]
                    : GOOD_ITEMS[Math.floor(Math.random() * GOOD_ITEMS.length)];

                newMap.set(index, {
                    id: Math.random(),
                    type: isBad ? 'bad' : 'good',
                    content,
                    expiresAt: Date.now() + 2000 // 2 seconds to click
                });
            }
            return newMap;
        });

        // Schedule next spawn
        spawnTimerRef.current = window.setTimeout(spawnItem, spawnRateRef.current);
    }, [isPlaying]);

    useEffect(() => {
        if (isPlaying) {
            spawnItem();
        }
        return () => {
            if (spawnTimerRef.current) clearTimeout(spawnTimerRef.current);
        };
    }, [isPlaying, spawnItem]);

    const startGame = () => {
        if (sessionState === 'expired') {
            addToast("Daily limit reached! Come back tomorrow.", "error");
            return;
        }
        setIsPlaying(true);
        setScore(0);
        setTimeLeft(GAME_DURATION);
        setCombo(1);
        setActiveCells(new Map());
        spawnRateRef.current = BASE_SPAWN_RATE;
        setFloatingTexts([]);
    };

    const endGame = (force?: boolean) => {
        setIsPlaying(false);
        if (spawnTimerRef.current) clearTimeout(spawnTimerRef.current);
        if (gameLoopRef.current) clearInterval(gameLoopRef.current);

        if (force) {
            addToast(`Session expired! Final Score: ${score}`, 'info');
        } else {
            if (score > highScore) {
                setHighScore(score);
                localStorage.setItem('spirit-blitz-highscore', score.toString());
                addToast(`New High Score: ${score}!`, 'success');
            } else {
                addToast(`Game Over! Score: ${score}`, 'info');
            }
        }
    };

    const handleTap = (index: number, e: React.MouseEvent) => {
        if (!isPlaying) return;

        const cell = activeCells.get(index);

        if (cell) {
            if (cell.type === 'good') {
                const points = 10 * combo;
                setScore(prev => prev + points);
                setCombo(prev => Math.min(prev + 1, 5)); // Cap combo at 5x
                addFloatingText(index, `+${points}`, 'text-green-500');
            } else {
                setScore(prev => Math.max(0, prev - 20));
                setCombo(1); // Reset combo
                addFloatingText(index, `-20`, 'text-red-500');
            }
            // Remove the clicked cell
            setActiveCells(prev => {
                const newMap = new Map(prev);
                newMap.delete(index);
                return newMap;
            });
        }
    };

    const addFloatingText = (index: number, text: string, color: string) => {
        const id = Date.now();
        setFloatingTexts(prev => [...prev, { id, text, x: index, y: 0, color }]);
        setTimeout(() => {
            setFloatingTexts(prev => prev.filter(ft => ft.id !== id));
        }, 800);
    };

    if (sessionState === 'checking') {
        return <div className="text-center p-8">Checking game access...</div>;
    }

    if (sessionState === 'expired') {
        return (
            <div className="max-w-md mx-auto py-12 px-4 animate-fade-in-up">
                <Card className="text-center border-t-4 border-red-500">
                    <div className="w-20 h-20 bg-red-100 rounded-full flex items-center justify-center mx-auto mb-4">
                        <ClockIcon className="w-10 h-10 text-red-600" />
                    </div>
                    <h2 className="text-2xl font-bold text-gray-800 dark:text-white mb-2">Game Center Closed</h2>
                    <p className="text-gray-600 dark:text-gray-300 mb-6">
                        You've used your 10 minutes of game time for today. This helps ensure we stay focused on our spiritual and academic goals!
                    </p>
                    <p className="font-semibold text-lg text-primary-600 mb-6">Come back tomorrow!</p>

                    <div className="flex flex-col gap-3">
                        <Button onClick={() => navigate('/tasks')} variant="primary" className="w-full">
                            <ClockIcon className="w-5 h-5 mr-2" /> Go to Tasks
                        </Button>
                        <Button onClick={() => navigate('/academics')} variant="outline" className="w-full">
                            <BookOpenIcon className="w-5 h-5 mr-2" /> Study Materials
                        </Button>
                    </div>
                </Card>
            </div>
        );
    }

    return (
        <div className="space-y-6 max-w-lg mx-auto pb-8">
            {/* Session Timer Banner */}
            <div className="bg-yellow-100 dark:bg-yellow-900/30 border border-yellow-200 dark:border-yellow-700 rounded-lg p-3 flex items-center justify-center gap-2 text-yellow-800 dark:text-yellow-200 text-sm font-bold animate-pulse">
                <ClockIcon className="w-4 h-4" />
                <span>Access Closes in: {formatSessionTime(sessionTimeLeft)}</span>
            </div>

            <h1 className="text-3xl font-bold text-center text-gray-800 dark:text-white flex items-center justify-center gap-2">
                <FireIcon className="w-8 h-8 text-orange-500" /> Spirit Blitz
            </h1>

            <Card className="relative overflow-hidden shadow-2xl border-4 border-gray-100 dark:border-gray-700">
                {/* HUD */}
                <div className="flex justify-between items-center mb-4 text-sm font-bold bg-white dark:bg-gray-800 p-2 rounded-lg shadow-sm">
                    <div className="flex flex-col items-center w-1/3">
                        <span className="text-gray-500 uppercase text-[10px]">Score</span>
                        <span className="text-xl md:text-2xl text-primary-600">{score}</span>
                    </div>
                    <div className="flex flex-col items-center w-1/3 border-x border-gray-200 dark:border-gray-700">
                        <span className="text-gray-500 uppercase text-[10px]">Time</span>
                        <span className={`text-xl md:text-2xl ${timeLeft < 10 ? 'text-red-500 animate-pulse' : 'text-gray-800 dark:text-gray-200'}`}>
                            {timeLeft}s
                        </span>
                    </div>
                    <div className="flex flex-col items-center w-1/3">
                        <span className="text-gray-500 uppercase text-[10px]">Combo</span>
                        <span className={`text-xl md:text-2xl ${combo > 1 ? 'text-yellow-500 scale-110' : 'text-gray-400'}`}>x{combo}</span>
                    </div>
                </div>

                {/* Game Grid */}
                <div className="grid grid-cols-3 gap-3 aspect-square bg-gray-200 dark:bg-gray-900 p-3 rounded-xl relative select-none">
                    {Array.from({ length: GRID_SIZE }).map((_, i) => {
                        const cell = activeCells.get(i);
                        return (
                            <div
                                key={i}
                                onClick={(e) => handleTap(i, e)}
                                className={`rounded-xl flex items-center justify-center text-center font-bold text-white shadow-md transition-all duration-75 active:scale-90 cursor-pointer relative overflow-hidden
                                    ${cell ? cell.content.color : 'bg-white dark:bg-gray-800 opacity-40'}
                                    ${cell ? 'scale-100' : 'scale-95'}
                                    ${cell ? 'ring-2 ring-white/50' : ''}
                                `}
                            >
                                {cell && (
                                    <div className="animate-bounce w-full h-full flex items-center justify-center">
                                        <span className="text-xs md:text-sm lg:text-base pointer-events-none drop-shadow-md leading-tight px-1">
                                            {cell.content.text}
                                        </span>
                                    </div>
                                )}

                                {/* Floating Text for this cell */}
                                {floatingTexts.filter(ft => ft.x === i).map(ft => (
                                    <div 
                                        key={ft.id}
                                        className={`absolute inset-0 flex items-center justify-center text-2xl font-black ${ft.color} animate-fade-in-up z-20`}
                                        style={{ animationDuration: '500ms', pointerEvents: 'none', textShadow: '0 2px 4px rgba(0,0,0,0.3)' }}
                                    >
                                        {ft.text}
                                    </div>
                                ))}
                            </div>
                        );
                    })}

                    {!isPlaying && timeLeft === GAME_DURATION && (
                        <div className="absolute inset-0 bg-black/60 backdrop-blur-sm flex flex-col items-center justify-center rounded-xl z-10 p-4">
                            <p className="text-white text-center mb-6 font-medium text-lg">
                                Tap <span className="text-green-400 font-bold">Fruits of the Spirit</span><br/>
                                Avoid <span className="text-red-400 font-bold">Works of Flesh</span>
                            </p>
                            <Button size="lg" onClick={startGame} className="animate-pulse shadow-xl border-2 border-primary-400 text-lg px-8 py-3">
                                <PlayIcon className="w-6 h-6 mr-2" /> Start
                            </Button>
                        </div>
                    )}

                    {!isPlaying && timeLeft <= 0 && (
                        <div className="absolute inset-0 bg-black/70 backdrop-blur-md flex flex-col items-center justify-center rounded-xl z-10">
                            <h2 className="text-4xl font-bold text-white mb-2">Time's Up!</h2>
                            <div className="bg-white/10 p-4 rounded-lg mb-6 text-center">
                                <p className="text-sm text-gray-300 uppercase">Final Score</p>
                                <p className="text-3xl text-yellow-400 font-black">{score}</p>
                            </div>
                            <Button size="lg" onClick={startGame}>
                                Play Again
                            </Button>
