const MATCH_ICONS = ['🕊️', '✝️', '📖', '👑', '🔥', '❤️', '🍞', '🍷'];

// --- TYPES ---
type GameType = 'blitz' | 'trivia' | 'scramble' | 'match' | 'echo' | null;

