// ==========================================
// SUB-COMPONENT: SPIRIT BLITZ
// ==========================================
const SpiritBlitzGame: React.FC<{ onScore: (s: number) => void, onEnd: () => void }> = ({ onScore, onEnd }) => {
    const [cells, setCells] = useState<Map<number, BlitzCell>>(new Map());
    const [score, setScore] = useState(0);
    const [timeLeft, setTimeLeft] = useState(30);
    const timerRef = useRef<number>();

    useEffect(() => {
        timerRef.current = window.setInterval(() => setTimeLeft(t => t - 1), 1000);
        return () => clearInterval(timerRef.current);
    }, []);

    useEffect(() => {
        if (timeLeft <= 0) {
            onScore(score);
            onEnd();
        }
    }, [timeLeft]);

    useEffect(() => {
        const spawn = setInterval(() => {
            setCells(prev => {
                const newMap = new Map(prev);
                // Clean expired
                const now = Date.now();
                Array.from(newMap.entries()).forEach(([k, v]) => { if (v.expires < now) newMap.delete(k); });
                // Spawn new
                if (newMap.size < 5) {
                    const idx = Math.floor(Math.random() * BLITZ_GRID_SIZE);
                    if (!newMap.has(idx)) {
                        const isBad = Math.random() < 0.3;
                        const item = isBad ? BLITZ_BAD[Math.floor(Math.random() * BLITZ_BAD.length)] : BLITZ_GOOD[Math.floor(Math.random() * BLITZ_GOOD.length)];
                        newMap.set(idx, { ...item, type: isBad ? 'bad' : 'good', expires: Date.now() + 1500, id: Math.random() });
                    }
                }
                return newMap;
            });
        }, 600);
        return () => clearInterval(spawn);
    }, []);

    const handleTap = (idx: number) => {
        const cell = cells.get(idx);
        if (!cell) return;
        if (cell.type === 'good') setScore(s => s + 10);
        else setScore(s => Math.max(0, s - 20));
        setCells(prev => { const n = new Map(prev); n.delete(idx); return n; });
    };

    return (
        <div className="space-y-4">
            <div className="flex justify-between font-bold text-xl">
                <span>Score: {score}</span>
                <span className="text-red-500">{timeLeft}s</span>
            </div>
            <div className="grid grid-cols-3 gap-3 aspect-square bg-gray-200 dark:bg-gray-800 p-3 rounded-xl">
                {Array.from({ length: BLITZ_GRID_SIZE }).map((_, i) => {
                    const cell = cells.get(i);
                    return (
                        <div key={i} onMouseDown={() => handleTap(i)} className={`rounded-lg flex items-center justify-center font-bold text-white transition-all cursor-pointer select-none ${cell ? cell.color : 'bg-white/10'} ${cell ? 'scale-100' : 'scale-95'}`}>
                            {cell?.text}
                        </div>
                    );
                })}
            </div>
        </div>
    );
};

// ==========================================
// SUB-COMPONENT: BIBLE TRIVIA
// ==========================================
const BibleTriviaGame: React.FC<{ onScore: (s: number) => void, onEnd: () => void }> = ({ onScore, onEnd }) => {
    const [qIndex, setQIndex] = useState(0);
    const [score, setScore] = useState(0);
    const [finished, setFinished] = useState(false);

    const handleAnswer = (idx: number) => {
        if (idx === TRIVIA_QUESTIONS[qIndex].c) setScore(s => s + 100);
        if (qIndex < TRIVIA_QUESTIONS.length - 1) {
            setQIndex(q => q + 1);
        } else {
            setFinished(true);
        }
    };

    useEffect(() => {
        if (finished) {
            onScore(score);
            // Small delay to show final state before closing
            setTimeout(onEnd, 2000); 
        }
    }, [finished]);

    if (finished) return <div className="text-center text-2xl font-bold py-10">Final Score: {score}</div>;

    const q = TRIVIA_QUESTIONS[qIndex];

    return (
        <div className="space-y-6 text-center">
            <div className="flex justify-between font-bold">
                <span>Q: {qIndex + 1}/{TRIVIA_QUESTIONS.length}</span>
