// MAIN COMPONENT: GAME CENTER
// ==========================================
const GameCenter: React.FC = () => {
    const { addToast } = useNotifier();
    const navigate = useNavigate();

    // Global State
    const [sessionState, setSessionState] = useState<'checking' | 'active' | 'expired'>('checking');
    const [sessionTimeLeft, setSessionTimeLeft] = useState<number>(0);
    const [activeGame, setActiveGame] = useState<GameType>(null);
    const [isPlaying, setIsPlaying] = useState(false);

    // --- SESSION MANAGEMENT (GLOBAL FOR ALL GAMES) ---
    useEffect(() => {
        const checkSession = () => {
            const now = Date.now();
            const today = new Date().toDateString();
            const storageKey = 'accf_game_session_v1';

            let session = null;
            try {
                const stored = localStorage.getItem(storageKey);
                if (stored) session = JSON.parse(stored);
            } catch(e) { console.error(e); }

            if (!session || session.date !== today) {
                const expiresAt = now + DAILY_ACCESS_LIMIT_MS;
                localStorage.setItem(storageKey, JSON.stringify({ date: today, expiresAt }));
                setSessionState('active');
                setSessionTimeLeft(DAILY_ACCESS_LIMIT_MS);
            } else {
                if (now >= session.expiresAt) {
                    setSessionState('expired');
                    setSessionTimeLeft(0);
                    if (isPlaying) endGame();
                } else {
                    setSessionState('active');
                    setSessionTimeLeft(session.expiresAt - now);
                }
            }
        };

        checkSession();
        const interval = setInterval(checkSession, 1000);
        return () => clearInterval(interval);
    }, [isPlaying]);

    const formatSessionTime = (ms: number) => {
        const totalSeconds = Math.max(0, Math.floor(ms / 1000));
        const minutes = Math.floor(totalSeconds / 60);
        const seconds = totalSeconds % 60;
        return `${minutes}m ${seconds}s`;
    };

    const startGame = (type: GameType) => {
        if (sessionState === 'expired') {
            addToast("Daily limit reached! Come back tomorrow.", "error");
            return;
        }
        setActiveGame(type);
        setIsPlaying(true);
    };

    const endGame = () => {
        setIsPlaying(false);
        setActiveGame(null);
    };

    const handleGameScore = (score: number) => {
        if (score > 0) {
            addToast(`Great Job! Score: ${score}`, 'success');
            // In a real app, save high score to DB here
        } else {
            addToast(`Game Over.`, 'info');
        }
    };

    if (sessionState === 'checking') return <div className="text-center p-8">Checking access...</div>;

    if (sessionState === 'expired') {
        return (
            <div className="max-w-md mx-auto py-12 px-4 animate-fade-in-up">
                <Card className="text-center border-t-4 border-red-500">
                    <div className="w-20 h-20 bg-red-100 rounded-full flex items-center justify-center mx-auto mb-4">
                        <ClockIcon className="w-10 h-10 text-red-600" />
                    </div>
                    <h2 className="text-2xl font-bold text-gray-800 dark:text-white mb-2">Arcade Closed</h2>
                    <p className="text-gray-600 dark:text-gray-300 mb-6">
                        You've used your 10 minutes of game time today. Stay focused on your spiritual goals!
                    </p>
                    <Button onClick={() => navigate('/tasks')} variant="primary" className="w-full">
                        <ClockIcon className="w-5 h-5 mr-2" /> Go to Tasks
                    </Button>
                </Card>
            </div>
        );
    }

    // --- GAME LOBBY VIEW ---
    if (!activeGame) {
        const games = [
            { id: 'blitz', name: 'Spirit Blitz', icon: <FireIcon className="w-8 h-8 text-orange-500"/>, desc: 'Tap Fruits of Spirit, avoid Flesh!', color: 'border-orange-200' },
            { id: 'trivia', name: 'Bible Trivia', icon: <BookOpenIcon className="w-8 h-8 text-blue-500"/>, desc: 'Test your scriptural knowledge.', color: 'border-blue-200' },
            { id: 'scramble', name: 'Verse Scramble', icon: <SparklesIcon className="w-8 h-8 text-purple-500"/>, desc: 'Unscramble the holy words.', color: 'border-purple-200' },
            { id: 'match', name: 'Divine Match', icon: <HeartIcon className="w-8 h-8 text-red-500"/>, desc: 'Find the matching pairs.', color: 'border-red-200' },
            { id: 'echo', name: 'Echo of Faith', icon: <CrownIcon className="w-8 h-8 text-yellow-500"/>, desc: 'Repeat the divine sequence.', color: 'border-yellow-200' },
        ];

        return (
            <div className="space-y-6 max-w-2xl mx-auto pb-8">
                <div className="bg-yellow-100 dark:bg-yellow-900/30 border border-yellow-200 dark:border-yellow-700 rounded-lg p-3 flex items-center justify-center gap-2 text-yellow-800 dark:text-yellow-200 text-sm font-bold">
                    <ClockIcon className="w-4 h-4" />
                    <span>Time Remaining: {formatSessionTime(sessionTimeLeft)}</span>
                </div>

                <h1 className="text-3xl font-bold text-center text-gray-800 dark:text-white mb-6">Fellowship Arcade</h1>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                    {games.map(g => (
                        <div 
                            key={g.id} 
                            onClick={() => startGame(g.id as GameType)}
                            className={`bg-white dark:bg-dark p-6 rounded-xl shadow-md cursor-pointer hover:shadow-xl hover:scale-105 transition-all border-b-4 ${g.color} flex flex-col items-center text-center`}
                        >
                            <div className="mb-3 p-3 bg-gray-50 dark:bg-gray-800 rounded-full">{g.icon}</div>
                            <h3 className="font-bold text-lg mb-1">{g.name}</h3>
                            <p className="text-sm text-gray-500">{g.desc}</p>
                        </div>
                    ))}
                </div>
            </div>
        );
    }

    // --- ACTIVE GAME VIEW ---
    return (
        <div className="max-w-lg mx-auto pb-8 space-y-4">
