const VerseScrambleGame: React.FC<{ onScore: (s: number) => void, onEnd: () => void }> = ({ onScore, onEnd }) => {
    const [verses, setVerses] = useState<any[]>([]);
    const [round, setRound] = useState(0);
    const [score, setScore] = useState(0);
    const [words, setWords] = useState<{id:number, t:string}[]>([]);
    const [selected, setSelected] = useState<{id:number, t:string}[]>([]);

    // Initialize random verses
    useEffect(() => {
        const sessionVerses = getRandomSubset(ALL_VERSES, 5);
        setVerses(sessionVerses);
    }, []);

    useEffect(() => {
        if (verses.length > 0) {
            if (round >= verses.length) {
                onScore(score);
                onEnd();
                return;
            }
            const verseWords = verses[round].text.split(' ').map((t: string, i: number) => ({ id: i, t }));
            setWords(shuffle(verseWords));
            setSelected([]);
        }
    }, [round, verses]);

    const handleWordClick = (word: {id:number, t:string}) => {
        const newSelected = [...selected, word];
        setSelected(newSelected);
        setWords(words.filter(w => w.id !== word.id));

        const currentPhrase = newSelected.map(w => w.t).join(' ');
        if (currentPhrase === verses[round].text) {
            setScore(s => s + 50);
            setTimeout(() => setRound(r => r + 1), 500);
        } else if (newSelected.length === verses[round].text.split(' ').length) {
            setTimeout(() => {
                const verseWords = verses[round].text.split(' ').map((t: string, i: number) => ({ id: i, t }));
                setWords(shuffle(verseWords));
                setSelected([]);
            }, 500);
        }
    };

    if (verses.length === 0) return <div className="text-center py-10">Loading Verses...</div>;
    if (round >= verses.length) return <div className="text-center py-10">Complete!</div>;

    return (
        <div className="space-y-6">
            <div className="flex justify-between font-bold">
                <span>Verse {round + 1}/{verses.length}</span>
                <span>Score: {score}</span>
            </div>
            <div className="min-h-[60px] p-4 bg-gray-100 dark:bg-gray-800 rounded-lg flex flex-wrap gap-2 justify-center">
                {selected.map(w => (
                    <span key={w.id} className="px-3 py-1 bg-primary-600 text-white rounded-md font-bold animate-fade-in-up">{w.t}</span>
                ))}
            </div>
            <div className="flex flex-wrap gap-3 justify-center">
                {words.map(w => (
                    <button key={w.id} onClick={() => handleWordClick(w)} className="px-4 py-2 bg-white dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-lg shadow-sm font-semibold active:scale-95 transition-transform">
                        {w.t}
                    </button>
                ))}
            </div>
            <p className="text-center text-sm text-gray-500 mt-4">Hint: {verses[round].ref}</p>
        </div>
    );
};

// ==========================================
// SUB-COMPONENT: DIVINE MATCH (DYNAMIC)
// ==========================================
const DivineMatchGame: React.FC<{ onScore: (s: number) => void, onEnd: () => void }> = ({ onScore, onEnd }) => {
    const [cards, setCards] = useState<{id:number, icon:string, matched:boolean, flipped:boolean}[]>([]);
    const [moves, setMoves] = useState(0);

    // Initialize random icons
    useEffect(() => {
        const sessionIcons = getRandomSubset(ALL_MATCH_ICONS, 8); // 8 pairs
        const deck = [...sessionIcons, ...sessionIcons]
            .sort(() => Math.random() - 0.5)
            .map((icon, id) => ({ id, icon, matched: false, flipped: false }));
        setCards(deck);
    }, []);

    const handleFlip = (id: number) => {
        const flipped = cards.filter(c => c.flipped && !c.matched);
        if (flipped.length >= 2) return;

        setCards(prev => prev.map(c => c.id === id ? { ...c, flipped: true } : c));

        if (flipped.length === 1) {
            setMoves(m => m + 1);
            const first = flipped[0];
            const second = cards.find(c => c.id === id);

            if (second && first.icon === second.icon) {
                setCards(prev => prev.map(c => (c.id === first.id || c.id === second.id) ? { ...c, matched: true } : c));
            } else {
                setTimeout(() => {
                    setCards(prev => prev.map(c => (c.id === first.id || c.id === id) ? { ...c, flipped: false } : c));
                }, 1000);
            }
        }
    };

    const isComplete = cards.length > 0 && cards.every(c => c.matched);

    useEffect(() => {
        if (isComplete) {
            const finalScore = Math.max(0, 1000 - (moves * 10));
            onScore(finalScore);
            setTimeout(onEnd, 2000);
        }
    }, [isComplete]);

    return (
        <div className="space-y-4">
            <div className="text-center font-bold">Moves: {moves}</div>
            <div className="grid grid-cols-4 gap-2">
                {cards.map(c => (
                    <div 
                        key={c.id} 
                        onClick={() => !c.flipped && !c.matched && handleFlip(c.id)}
                        className={`aspect-square rounded-lg flex items-center justify-center text-3xl cursor-pointer transition-all duration-300 transform ${c.flipped || c.matched ? 'bg-white dark:bg-gray-700 rotate-y-180' : 'bg-primary-600 text-transparent'}`}
                    >
                        {(c.flipped || c.matched) ? c.icon : '?'}
                    </div>
                ))}
            </div>
        </div>
    );
};

// ==========================================
// SUB-COMPONENT: SHEPHERD'S SNAKE (Replaces Echo)
// ==========================================
const ShepherdSnakeGame: React.FC<{ onScore: (s: number) => void, onEnd: () => void }> = ({ onScore, onEnd }) => {
    const GRID_SIZE = 15;
    const SPEED = 200;

    // Initial State
    const [snake, setSnake] = useState([{x: 7, y: 7}]);
    const [food, setFood] = useState({x: 3, y: 3});
    const [direction, setDirection] = useState({x: 0, y: -1}); // Start moving UP
    const [score, setScore] = useState(0);
    const [isGameOver, setIsGameOver] = useState(false);

    const gameLoopRef = useRef<number>();
    const directionRef = useRef({x: 0, y: -1}); // Ref to prevent multiple direction changes per tick

    const generateFood = () => {
        let newFood;
        do {
            newFood = {
                x: Math.floor(Math.random() * GRID_SIZE),
                y: Math.floor(Math.random() * GRID_SIZE)
            };
        } while (snake.some(segment => segment.x === newFood.x && segment.y === newFood.y));
        setFood(newFood);
    };

    const gameOver = () => {
        setIsGameOver(true);
        if (gameLoopRef.current) clearInterval(gameLoopRef.current);
        onScore(score * 10);
        setTimeout(onEnd, 3000);
    };

    const moveSnake = useCallback(() => {
        if (isGameOver) return;

        setSnake(prevSnake => {
            const head = prevSnake[0];
            const newHead = {
                x: head.x + directionRef.current.x,
                y: head.y + directionRef.current.y
            };

            // Wall Collision
            if (newHead.x < 0 || newHead.x >= GRID_SIZE || newHead.y < 0 || newHead.y >= GRID_SIZE) {
                gameOver();
                return prevSnake;
            }

            // Self Collision
            if (prevSnake.some(segment => segment.x === newHead.x && segment.y === newHead.y)) {
                gameOver();
                return prevSnake;
            }

            const newSnake = [newHead, ...prevSnake];

            // Food Collision
            if (newHead.x === food.x && newHead.y === food.y) {
                setScore(s => s + 1);
                generateFood();
            } else {
                newSnake.pop(); // Remove tail if no food eaten
            }

            return newSnake;
        });
    }, [food, isGameOver]);

    // Handle Controls
    const changeDirection = (newDir: {x: number, y: number}) => {
        // Prevent reversing directly
        if (newDir.x === -directionRef.current.x && newDir.y === -directionRef.current.y) return;
        directionRef.current = newDir;
        setDirection(newDir);
    };

    // Keyboard controls
    useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
            switch(e.key) {
                case 'ArrowUp': changeDirection({x: 0, y: -1}); break;
                case 'ArrowDown': changeDirection({x: 0, y: 1}); break;
                case 'ArrowLeft': changeDirection({x: -1, y: 0}); break;
                case 'ArrowRight': changeDirection({x: 1, y: 0}); break;
            }
        };
        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, []);

    // Game Loop
    useEffect(() => {
        if (!isGameOver) {
            gameLoopRef.current = window.setInterval(moveSnake, SPEED);
        }
        return () => clearInterval(gameLoopRef.current);
    }, [moveSnake, isGameOver]);

    // Update food state ref for generateFood closure if needed, but setState handles it.

    return (
        <div className="space-y-4 text-center">
            <div className="font-bold text-xl flex justify-between">
                <span>Sheep Found: {score}</span>
                {isGameOver && <span className="text-red-500 animate-pulse">GAME OVER</span>}
            </div>

            {/* Game Board */}
            <div 
                className="bg-gray-800 rounded-lg mx-auto relative overflow-hidden shadow-inner border-4 border-gray-600"
                style={{
                    width: '300px',
                    height: '300px',
                    display: 'grid',
                    gridTemplateColumns: `repeat(${GRID_SIZE}, 1fr)`,
                    gridTemplateRows: `repeat(${GRID_SIZE}, 1fr)`
                }}
            >
                {Array.from({ length: GRID_SIZE * GRID_SIZE }).map((_, i) => {
                    const x = i % GRID_SIZE;
                    const y = Math.floor(i / GRID_SIZE);
                    const isSnakeHead = snake[0].x === x && snake[0].y === y;
                    const isSnakeBody = snake.some((s, idx) => idx !== 0 && s.x === x && s.y === y);
                    const isFood = food.x === x && food.y === y;

                    let content = null;
                    if (isSnakeHead) content = <div className="w-full h-full bg-green-400 rounded-sm z-10" />;
                    else if (isSnakeBody) content = <div className="w-full h-full bg-green-600 rounded-sm" />;
                    else if (isFood) content = <div className="w-full h-full flex items-center justify-center text-xs">🐑</div>;

                    return <div key={i} className="relative">{content}</div>;
                })}
            </div>

            {/* Mobile Controls */}
            <div className="grid grid-cols-3 gap-2 max-w-[200px] mx-auto">
                <div></div>
                <Button size="sm" variant="secondary" onClick={() => changeDirection({x: 0, y: -1})}>▲</Button>
                <div></div>
                <Button size="sm" variant="secondary" onClick={() => changeDirection({x: -1, y: 0})}>◄</Button>
                <Button size="sm" variant="secondary" onClick={() => changeDirection({x: 0, y: 1})}>▼</Button>
                <Button size="sm" variant="secondary" onClick={() => changeDirection({x: 1, y: 0})}>►</Button>
            </div>
            <p className="text-xs text-gray-500">Collect the lost sheep! Don't hit walls.</p>
        </div>
    );
};


