const BibleTriviaGame: React.FC<{ onScore: (s: number) => void, onEnd: () => void }> = ({ onScore, onEnd }) => {
    const [questions, setQuestions] = useState<any[]>([]);
    const [qIndex, setQIndex] = useState(0);
    const [score, setScore] = useState(0);
    const [finished, setFinished] = useState(false);

    // Initialize with a random subset of questions
    useEffect(() => {
        const sessionQuestions = getRandomSubset(ALL_TRIVIA_QUESTIONS, 7); // 7 questions per round
        setQuestions(sessionQuestions);
    }, []);

    const handleAnswer = (idx: number) => {
        if (idx === questions[qIndex].c) setScore(s => s + 100);
        if (qIndex < questions.length - 1) {
            setQIndex(q => q + 1);
        } else {
            setFinished(true);
        }
    };

    useEffect(() => {
        if (finished) {
            onScore(score);
            setTimeout(onEnd, 2000); 
        }
    }, [finished]);

    if (questions.length === 0) return <div className="text-center py-10">Loading Questions...</div>;
    if (finished) return <div className="text-center text-2xl font-bold py-10">Final Score: {score}</div>;

    const q = questions[qIndex];

    return (
        <div className="space-y-6 text-center">
            <div className="flex justify-between font-bold">
                <span>Q: {qIndex + 1}/{questions.length}</span>
                <span>Score: {score}</span>
            </div>
            <h3 className="text-xl font-bold h-24 flex items-center justify-center px-2">{q.q}</h3>
            <div className="grid grid-cols-1 gap-3">
                {q.a.map((opt: string, i: number) => (
                    <Button key={i} variant="outline" onClick={() => handleAnswer(i)} className="py-4 text-lg border-2">
                        {opt}
                    </Button>
                ))}
            </div>
        </div>
    );
};

