import React, { useState, useEffect, useRef, Suspense, lazy } from 'react';
import { useAppContext } from '../../context/AppContext';
import { useNotifier } from '../../context/NotificationContext';
import { supabase } from '../../lib/supabaseClient';
import Card from '../ui/Card';
import Button from '../ui/Button';
import { XIcon, ClockIcon, PlayIcon, PauseIcon, CheckCircleIcon, FireIcon, RefreshIcon, BookOpenIcon, PencilAltIcon } from '../ui/Icons';
import { UserCourseMaterial } from '../../types';

const AutoSaveField = lazy(() => import('../ui/AutoSaveField'));

interface FocusStudyModalProps {
    material: UserCourseMaterial;
    onClose: () => void;
}

const SESSION_DURATION = 25 * 60; // 25 minutes in seconds
const COIN_REWARD = 10;

const FocusStudyModal: React.FC<FocusStudyModalProps> = ({ material, onClose }) => {
    const { currentUser } = useAppContext();
    const { addToast } = useNotifier();

    // Timer State
    const [timeLeft, setTimeLeft] = useState(SESSION_DURATION);
    const [isActive, setIsActive] = useState(false);
    const [isCompleted, setIsCompleted] = useState(false);
    const [isProcessingReward, setIsProcessingReward] = useState(false);

    // Notes State
    const [showNotes, setShowNotes] = useState(true);
    const [notes, setNotes] = useState('');

    useEffect(() => {
        let interval: number | null = null;

        if (isActive && timeLeft > 0) {
            interval = window.setInterval(() => {
                setTimeLeft((time) => time - 1);
            }, 1000);
        } else if (timeLeft === 0 && isActive) {
            setIsActive(false);
            setIsCompleted(true);
            if (interval) clearInterval(interval);
            // Play a sound or vibrate here if desired
        }

        return () => {
            if (interval) clearInterval(interval);
        };
    }, [isActive, timeLeft]);

    const toggleTimer = () => setIsActive(!isActive);

    const resetTimer = () => {
        setIsActive(false);
        setTimeLeft(SESSION_DURATION);
        setIsCompleted(false);
    };

    const handleClaimReward = async () => {
        if (!currentUser || !supabase || isProcessingReward) return;

        setIsProcessingReward(true);

        try {
            // Record transaction
            const { error } = await supabase.from('coin_transactions').insert({
                user_id: currentUser.id,
                source_type: 'task', // Using task as generic source
                source_id: material.id,
                coin_amount: COIN_REWARD,
                status: 'pending',
                reason: `Completed study session: ${material.title}`
            });

            if (error) throw error;

            addToast(`Great focus! ${COIN_REWARD} coins pending approval.`, 'success');

            // Log streak activity if needed
            await supabase.rpc('update_user_streak', { p_user_id: currentUser.id });

            onClose();
        } catch (error: any) {
            addToast('Error claiming reward: ' + error.message, 'error');
            setIsProcessingReward(false);
        }
    };

    const formatTime = (seconds: number) => {
        const mins = Math.floor(seconds / 60);
        const secs = seconds % 60;
        return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
    };

    const progressPercentage = ((SESSION_DURATION - timeLeft) / SESSION_DURATION) * 100;

    return (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-sm z-50 flex items-center justify-center p-4 animate-fade-in-up">
            <Card className="w-full max-w-lg relative flex flex-col max-h-[90vh] overflow-hidden !p-0">
                {/* Header */}
                <div className="p-4 border-b dark:border-gray-700 flex justify-between items-center bg-gray-50 dark:bg-gray-800">
                    <div className="flex items-center gap-2 overflow-hidden">
                        <div className="p-2 bg-blue-100 dark:bg-blue-900/30 rounded-full text-blue-600 dark:text-blue-400">
                            <ClockIcon className="w-5 h-5" />
                        </div>
                        <div className="min-w-0">
                            <h2 className="font-bold text-gray-800 dark:text-white truncate">Focus Session</h2>
                            <p className="text-xs text-gray-500 truncate">{material.courses?.code} - {material.title}</p>
                        </div>
                    </div>
                    <button onClick={onClose} className="p-2 hover:bg-gray-200 dark:hover:bg-gray-700 rounded-full">
                        <XIcon className="w-5 h-5 text-gray-500" />
                    </button>
                </div>

                <div className="overflow-y-auto flex-1 p-6 flex flex-col items-center">

                    {/* Timer Display */}
                    <div className="relative mb-8">
                        {/* Circular Progress (SVG) */}
                        <div className="w-64 h-64 relative flex items-center justify-center">
                            <svg className="w-full h-full transform -rotate-90">
                                <circle
                                    cx="128"
                                    cy="128"
                                    r="120"
                                    stroke="currentColor"
                                    strokeWidth="8"
                                    fill="transparent"
                                    className="text-gray-200 dark:text-gray-700"
                                />
                                <circle
                                    cx="128"
                                    cy="128"
                                    r="120"
                                    stroke="currentColor"
                                    strokeWidth="8"
                                    fill="transparent"
                                    strokeDasharray={2 * Math.PI * 120}
                                    strokeDashoffset={2 * Math.PI * 120 * (1 - progressPercentage / 100)}
                                    className="text-primary-500 transition-all duration-1000 ease-linear"
                                />
                            </svg>
                            <div className="absolute inset-0 flex flex-col items-center justify-center">
                                <span className="text-5xl font-mono font-bold text-gray-800 dark:text-white tabular-nums">
                                    {formatTime(timeLeft)}
                                </span>
                                <span className="text-sm text-gray-500 mt-2 uppercase tracking-widest font-semibold">
                                    {isActive ? 'Focusing' : isCompleted ? 'Completed' : 'Ready'}
                                </span>
                            </div>
                        </div>
                    </div>

                    {/* Actions */}
                    <div className="flex gap-4 w-full justify-center mb-8">
                        {!isCompleted ? (
                            <>
                                <Button 
                                    onClick={toggleTimer} 
                                    size="lg" 
                                    className={`w-32 ${isActive ? 'bg-yellow-500 hover:bg-yellow-600' : 'bg-primary-600 hover:bg-primary-700'}`}
                                >
                                    {isActive ? <><PauseIcon className="w-5 h-5 mr-2" /> Pause</> : <><PlayIcon className="w-5 h-5 mr-2" /> Start</>}
                                </Button>
                                <Button onClick={resetTimer} variant="secondary" size="lg">
                                    <RefreshIcon className="w-5 h-5" />
                                </Button>
                            </>
                        ) : (
                            <Button 
                                onClick={handleClaimReward} 
                                size="lg" 
                                className="w-full bg-gradient-to-r from-yellow-500 to-amber-600 hover:from-yellow-600 hover:to-amber-700 border-none shadow-lg animate-pulse"
                                disabled={isProcessingReward}
                            >
                                <FireIcon className="w-5 h-5 mr-2" />
                                {isProcessingReward ? 'Claiming...' : `Claim ${COIN_REWARD} Coins`}
                            </Button>
                        )}
                    </div>

                    {/* Notes Section */}
                    <div className="w-full border-t dark:border-gray-700 pt-6">
                        <div className="flex justify-between items-center mb-2">
                            <h3 className="font-semibold text-gray-700 dark:text-gray-300 flex items-center gap-2">
                                <PencilAltIcon className="w-4 h-4" /> Session Notes
                            </h3>
                            <span className="text-xs text-gray-400">Auto-saved to this device</span>
                        </div>
                        <Suspense fallback={<div className="h-32 bg-gray-100 rounded"></div>}>
                            <AutoSaveField
                                as="textarea"
                                storageKey={`study-notes-${material.id}`}
                                value={notes}
                                onChange={(e) => setNotes(e.target.value)}
                                placeholder="Jot down key concepts, formulas, or reminders here..."
                                className="w-full h-32 p-3 bg-yellow-50 dark:bg-yellow-900/10 border border-yellow-200 dark:border-yellow-800/30 rounded-lg text-sm focus:ring-yellow-500 focus:border-yellow-500 resize-none"
                            />
                        </Suspense>
                    </div>
                </div>
            </Card>
        </div>
    );
};

export default FocusStudyModal;

